    walsh_hadamard_transform(left, False, mod)
    walsh_hadamard_transform(right, False, mod)
    for index in range(len(left)):
        left[index] = left[index] * right[index] % mod
    walsh_hadamard_transform(left, True, mod)
    return left


class SubsetConvolution:
    __slots__ = ("mod",)

    def __init__(self, mod=DEFAULT_MOD):
        if mod <= 1:
            raise ValueError("mod must define a field")
        self.mod = mod

    def _lift_and_zeta(self, first, second):
        size = len(first)
        bits = (size - 1).bit_length()
        width = bits + 1
        popcount = _popcounts(size)
        total = size * width
        left = [0] * total
        right = [0] * total
        mod = self.mod
        for mask in range(size):
            position = mask * width + popcount[mask]
            left[position] = first[mask] % mod
            right[position] = second[mask] % mod
        step = 1
        while step < size:
            block = step << 1
            for start in range(0, size, block):
                for offset in range(step):
                    source = start + offset
                    target = source + step
                    source_position = source * width
                    target_position = target * width
                    limit = popcount[target]
                    for rank in range(limit):
                        left[target_position + rank] += left[
                            source_position + rank
                        ]
                        right[target_position + rank] += right[
                            source_position + rank
                        ]
            step = block
        return left, right, popcount, bits, width

    def _mobius_and_unlift(self, values, popcount, bits, width):
        size = len(popcount)
        step = size >> 1
        while step:
            block = step << 1
            for start in range(0, size, block):
                for offset in range(step):
                    source = start + offset
                    target = source + step
                    source_position = source * width
                    target_position = target * width
                    for rank in range(popcount[target], bits + 1):
                        values[target_position + rank] -= values[
                            source_position + rank
                        ]
            step >>= 1
        mod = self.mod
        return [
            values[mask * width + popcount[mask]] % mod
            for mask in range(size)
        ]

    def multiply(self, first, second):
        _check_pair(first, second)
        left, right, popcount, bits, width = self._lift_and_zeta(
            first, second
        )
        mod = self.mod
        scratch = [0] * width
        for mask, degree in enumerate(popcount):
            position = mask * width
            for total_degree in range(bits + 1):
                lower = max(0, total_degree - degree)
                upper = min(total_degree, degree)
                value = 0
                for rank in range(lower, upper + 1):
                    value += (
                        left[position + rank]
                        * right[position + total_degree - rank]
                    )
                scratch[total_degree] = value % mod
            for rank in range(width):
                left[position + rank] = scratch[rank]
        return self._mobius_and_unlift(
            left, popcount, bits, width
        )

    def divide(self, dividend, divisor):
        _check_pair(dividend, divisor)
        try:
            inverse_constant = pow(divisor[0] % self.mod, -1, self.mod)
        except ValueError as error:
            raise ZeroDivisionError(
                "divisor[0] must be invertible modulo mod"
            ) from error
        left, right, popcount, bits, width = self._lift_and_zeta(
            dividend, divisor
        )
        mod = self.mod
        scratch = [0] * width
        for mask in range(len(popcount)):
            position = mask * width
            for degree in range(bits + 1):
                value = left[position + degree]
                for rank in range(degree):
                    value -= scratch[rank] * right[
                        position + degree - rank
                    ]
                scratch[degree] = value * inverse_constant % mod
            for degree in range(width):
                left[position + degree] = scratch[degree]
        return self._mobius_and_unlift(
            left, popcount, bits, width
        )

    def transpose_multiply(self, first, second):
        result = self.multiply(list(reversed(first)), second)
        result.reverse()
        return result

    def exponential(self, series):
        _check_size(len(series))
        if series[0] % self.mod:
            raise ValueError("set-series exponential requires series[0] = 0")
        result = [0] * len(series)
        result[0] = 1
        bits = (len(series) - 1).bit_length()
        for bit in range(bits):
            half = 1 << bit
            upper = half << 1
            result[half:upper] = self.multiply(
                result[:half], series[half:upper]
            )
        return result

    def logarithm(self, series):
        _check_size(len(series))
        if series[0] % self.mod != 1:
            raise ValueError("set-series logarithm requires series[0] = 1")
        result = [0] * len(series)
        bits = (len(series) - 1).bit_length()
        for bit in range(bits - 1, -1, -1):
            half = 1 << bit
            upper = half << 1
            result[half:upper] = self.divide(
                series[half:upper], series[:half]
            )
        return result

    def compose_egf(self, series, derivatives):
        _check_size(len(series))
        if series[0] % self.mod:
            raise ValueError("EGF composition requires series[0] = 0")
        bits = (len(series) - 1).bit_length()
        coefficients = [value % self.mod for value in derivatives[:bits + 1]]
        coefficients.extend([0] * (bits + 1 - len(coefficients)))
        current = [coefficients[bits]]
        for degree in range(bits - 1, -1, -1):
            stages = bits - degree
            next_values = [0] * (1 << stages)
            next_values[0] = coefficients[degree]
            for stage in range(stages):
                half = 1 << stage
                next_values[half:half << 1] = self.multiply(
                    current[:half], series[half:half << 1]
                )
            current = next_values
        return current

    def compose(self, outer, series):
        _check_size(len(series))
        from library_codex.fps.FormalPowerSeries import (
            fps_taylor_shift,
        )

        bits = (len(series) - 1).bit_length()
        shifted = fps_taylor_shift(outer, series[0], self.mod) if outer else []
        shifted.extend([0] * (bits + 1 - len(shifted)))
        factorial = 1
        derivatives = [0] * (bits + 1)
        for degree in range(bits + 1):
            if degree:
                factorial = factorial * degree % self.mod
            derivatives[degree] = shifted[degree] * factorial % self.mod
        zero_constant = [value % self.mod for value in series]
        zero_constant[0] = 0
        return self.compose_egf(zero_constant, derivatives)

    def transpose_compose_egf(self, series, weights):
        _check_pair(series, weights)
        if series[0] % self.mod:
            raise ValueError("transpose EGF composition requires series[0] = 0")
        bits = (len(series) - 1).bit_length()
        current = [value % self.mod for value in weights]
        result = [0] * (bits + 1)
        result[0] = current[0]
        for degree in range(bits):
            next_size = 1 << (bits - degree - 1)
            next_values = [0] * next_size
            for stage in range(bits - degree - 1, -1, -1):
                half = 1 << stage
                product = self.transpose_multiply(
                    current[half:half << 1],
                    series[half:half << 1],
                )
                for index, value in enumerate(product):
                    next_values[index] = (
                        next_values[index] + value
                    ) % self.mod
            current = next_values
            result[degree + 1] = current[0]
        return result

    def power_projection(self, series, weights, terms, exponential=False):
        _check_pair(series, weights)
        if terms < 0:
            raise ValueError("terms must be nonnegative")
        if terms == 0:
            return []
        mod = self.mod
        constant = series[0] % mod
        zero_constant = [value % mod for value in series]
        zero_constant[0] = 0
        derivatives = self.transpose_compose_egf(
            zero_constant, weights
        )
        bits = len(derivatives) - 1
        limit = max(bits, terms - 1)
        if limit >= mod:
            raise ValueError("factorials must be invertible modulo mod")
        factorial = [1] * (limit + 1)
        for index in range(1, limit + 1):
            factorial[index] = factorial[index - 1] * index % mod
        inverse_factorial = [1] * (limit + 1)
        inverse_factorial[-1] = pow(factorial[-1], -1, mod)
        for index in range(limit, 0, -1):
            inverse_factorial[index - 1] = (
                inverse_factorial[index] * index % mod
            )
        coefficients = [0] * terms
        power = 1
        for shift in range(terms):
            scale = power * inverse_factorial[shift] % mod
            upper = min(bits, terms - 1 - shift)
            for degree in range(upper + 1):
                coefficients[shift + degree] = (
                    coefficients[shift + degree]
                    + scale * derivatives[degree]
                ) % mod
            power = power * constant % mod
        for index in range(terms):
            coefficients[index] = coefficients[index] * factorial[index] % mod
            if exponential:
                coefficients[index] = (
                    coefficients[index] * inverse_factorial[index] % mod
                )
        return coefficients


def subset_convolution(first, second, mod=DEFAULT_MOD):
    return SubsetConvolution(mod).multiply(first, second)


def subset_convolution_divide(dividend, divisor, mod=DEFAULT_MOD):
    return SubsetConvolution(mod).divide(dividend, divisor)


def set_series_exponential(series, mod=DEFAULT_MOD):
    return SubsetConvolution(mod).exponential(series)


def set_series_logarithm(series, mod=DEFAULT_MOD):
    return SubsetConvolution(mod).logarithm(series)


def set_series_composition(outer, series, mod=DEFAULT_MOD):
    return SubsetConvolution(mod).compose(outer, series)


def set_series_power_projection(
    series, weights, terms, mod=DEFAULT_MOD, exponential=False
):
    return SubsetConvolution(mod).power_projection(
        series, weights, terms, exponential
    )


or_convolution = bitwise_or_convolution
and_convolution = bitwise_and_convolution
xor_convolution = bitwise_xor_convolution
walsh_hadamard_tranform = walsh_hadamard_transform
polynomial_composite_set_power_series = set_series_composition
power_projection_of_set_power_series = set_series_power_projection

"""998244353上でFPS合成と合成逆関数を計算する。

`fps_compose(outer, inner, degree)`は`outer(inner(x)) mod x^degree`、
`fps_compositional_inv(series, degree)`は`series(g(x))=x mod x^degree`
となる`g`の係数列を返す。
"""

from array import array

from library_codex.convolution.NTT998 import (
    MOD,
    _butterfly,
    _check_length,
    _intt,
)
from library_codex.fps998.FPS import fps_exp, fps_inv, fps_log
from library_codex.fps998.PowerProjection import power_coefficient
from library_codex.convolution.NTT998 import multiply


def _add_constant(series, value):
    if series:
        series[0] = (series[0] + value) % MOD
    else:
        series.append(value % MOD)


def _compose_naive(outer, inner, degree):
    result = []
    inner = [value % MOD for value in inner[:degree]]
    for coefficient in reversed(outer[:degree]):
        result = multiply(result, inner)[:degree]
        _add_constant(result, coefficient)
    result.extend([0] * (degree - len(result)))
    return result


def _build_frequency_q(series, n, height, blocks):
    total = 4 * height * blocks
    frequency = [0] * total
    for block in range(blocks):
        source = block * height
        target = block * height * 2
        frequency[target:target + n + 1] = series[source:source + n + 1]
    frequency[blocks * height * 2] = (
        frequency[blocks * height * 2] + 1
    ) % MOD
    _butterfly(frequency)
    for index in range(0, total, 2):
        frequency[index], frequency[index + 1] = (
            frequency[index + 1], frequency[index]
        )
    return frequency


def _descend_q(series, n, height, blocks):
    frequency = _build_frequency_q(series, n, height, blocks)
    half_total = 2 * height * blocks
    reduced = [0] * half_total
    for index in range(half_total):
        reduced[index] = (
            frequency[index << 1] * frequency[index << 1 | 1] % MOD
        )
    _intt(reduced)
    reduced[0] = (reduced[0] - 1) % MOD
    child_height = height >> 1
    child = [0] * (height * blocks)
    child_degree = n >> 1
    for block in range(blocks << 1):
        source = block * height
        target = block * child_height
        child[target:target + child_degree + 1] = reduced[
            source:source + child_degree + 1
        ]
    return child, array("I", frequency)


def _reverse_frequency_blocks(values):
    start = 1
    while start < len(values):
        left = start
        right = (start << 1) - 1
        while left < right:
            values[left], values[right] = values[right], values[left]
            left += 1
            right -= 1
        start <<= 1


def _ascend_p(child, frequency_q, n, height, blocks):
    total = len(frequency_q)
    frequency_p = [0] * total
    child_height = height >> 1
    child_degree = n >> 1
    parity = n & 1
    for block in range(blocks << 1):
        source = block * child_height
        target = block * height * 2 + parity
        for index in range(child_degree + 1):
            frequency_p[target + (index << 1)] = child[source + index]
    _butterfly(frequency_p)
    _reverse_frequency_blocks(frequency_q)
    for index in range(total):
        frequency_p[index] = frequency_p[index] * frequency_q[index] % MOD
    _intt(frequency_p)
    result = [0] * (height * blocks)
    for block in range(blocks):
        source = block * height * 2
        target = block * height
        result[target:target + n + 1] = frequency_p[source:source + n + 1]
    return result


def _compose_ntt(outer, inner, degree):
    original_degree = degree - 1
    height = 1 << (degree - 1).bit_length()
    _check_length(height << 2)
    fixed_size = height
    outer_values = [value % MOD for value in outer[:degree]]
    outer_values.extend([0] * (degree - len(outer_values)))
    current = [0] * fixed_size
    for index, value in enumerate(inner[:degree]):
        current[index] = -value % MOD
    frames = []
    n = original_degree
    block_height = height
    blocks = 1
    while n:
        current, frequency_q = _descend_q(
            current, n, block_height, blocks
        )
        frames.append((frequency_q, n, block_height, blocks))
        n >>= 1
        block_height >>= 1
        blocks <<= 1

    denominator = current[:blocks]
    denominator.append(1)
    denominator.reverse()
    inverse = fps_inv(denominator, len(denominator))
    inverse.reverse()
    product = multiply(outer_values, inverse)
    result = [0] * fixed_size
    for index in range(degree):
        result[blocks - 1 - index] = product[index + blocks]

    while frames:
        frequency_q, n, block_height, blocks = frames.pop()
        result = _ascend_p(
            result, frequency_q, n, block_height, blocks
        )
    result = result[:degree]
    result.reverse()
    return result


def fps_compose(outer, inner, degree=None):
    """`outer(inner(x)) mod x^degree`の係数を`degree`個返す。O(N log^2 N)。"""

    if degree is None:
        degree = max(len(outer), len(inner))
    if degree < 0:
        raise ValueError("degree must be nonnegative")
    if degree == 0:
        return []
    if not outer:
        return [0] * degree
    if len(outer) == 1:
        return [outer[0] % MOD] + [0] * (degree - 1)
    if len(inner) <= 1:
        point = inner[0] % MOD if inner else 0
        value = 0
        for coefficient in reversed(outer[:degree]):
            value = (value * point + coefficient) % MOD
        return [value] + [0] * (degree - 1)
    if inner[0] % MOD == 0 and inner[1] % MOD == 1 and len(inner) == 2:
        result = [value % MOD for value in outer[:degree]]
        result.extend([0] * (degree - len(result)))
        return result
    if degree <= 64:
        return _compose_naive(outer, inner, degree)
    return _compose_ntt(outer, inner, degree)


def fps_compositional_inv(series, degree=None):
    """`series(g(x))=x mod x^degree`となる`g`の係数を返す。O(N log^2 N)。"""

    if degree is None:
        degree = len(series)
    if degree < 0:
        raise ValueError("degree must be nonnegative")
    if degree == 0:
        return []
    if not series or series[0] % MOD:
        raise ValueError("compositional inverse requires series[0] = 0")
    if len(series) < 2 or series[1] % MOD == 0:
        raise ValueError("a nonzero linear coefficient is required")
    inverse_linear = pow(series[1] % MOD, MOD - 2, MOD)
    if degree == 1:
        return [0]
    last = min(len(series), degree) - 1
    while last > 1 and series[last] % MOD == 0:
        last -= 1
    if last == 1:
        return [0, inverse_linear] + [0] * (degree - 2)

    order = degree - 1
    source = [value % MOD for value in series[:degree]]
    source.extend([0] * (degree - len(source)))
    coefficients = power_coefficient(source, count=degree)

    inverses = [0] * degree
    inverses[1] = 1
    for index in range(2, degree):
        inverses[index] = (
            -(MOD // index) * inverses[MOD % index]
        ) % MOD
    for index in range(1, degree):
        coefficients[index] = (
            coefficients[index] * order * inverses[index]
        ) % MOD

    coefficients.reverse()
    scale = pow(coefficients[0], MOD - 2, MOD)
    for index in range(degree):
        coefficients[index] = coefficients[index] * scale % MOD

    exponent = -pow(order, MOD - 2, MOD) % MOD
    logarithm = fps_log(coefficients, degree - 1)
    for index in range(degree - 1):
        logarithm[index] = logarithm[index] * exponent % MOD
    result = fps_exp(logarithm, degree - 1)
    for index in range(degree - 1):
        result[index] = result[index] * inverse_linear % MOD
    return [0] + result

"""998244353上の形式的冪級数を昇べき順の係数listで計算する。

`a[i]`は$x^i$の係数を表す。inv・log・exp・pow・sqrt、微分・積分、
多項式除算、Taylor shift、一括積を固定modのradix-4 NTTで計算する。
入力listは変更せず、新しい係数listを返す。
"""

from heapq import heapify, heappop, heappush

from library_codex.convolution.NTT998 import (
    MOD,
    _butterfly,
    _check_length,
    _intt,
    multiply,
)


_INVERSES = [0, 1]
_SPARSE_INV_THRESHOLD = 160
_SPARSE_DIV_THRESHOLD = 200
_SPARSE_LOG_THRESHOLD = 200
_SPARSE_EXP_THRESHOLD = 320
_SPARSE_POWER_THRESHOLD = 32


def _mod_sqrt(value):
    value %= MOD
    if value < 2:
        return value
    if pow(value, (MOD - 1) >> 1, MOD) != 1:
        return -1
    odd = MOD - 1
    exponent = 0
    while odd & 1 == 0:
        odd >>= 1
        exponent += 1
    nonresidue = 3
    root = pow(value, (odd + 1) >> 1, MOD)
    remainder = pow(value, odd, MOD)
    generator = pow(nonresidue, odd, MOD)
    level = exponent
    while remainder != 1:
        position = 1
        squared = remainder * remainder % MOD
        while position < level and squared != 1:
            squared = squared * squared % MOD
            position += 1
        if position == level:
            return -1
        adjustment = pow(generator, 1 << (level - position - 1), MOD)
        root = root * adjustment % MOD
        adjustment = adjustment * adjustment % MOD
        remainder = remainder * adjustment % MOD
        generator = adjustment
        level = position
    return min(root, MOD - root)


def _degree(degree, default):
    if degree is None:
        return default
    if degree < 0:
        raise ValueError("degree must be nonnegative")
    return degree


def _inverses(size):
    if size >= MOD:
        raise ValueError("formal integration requires degree < 998244353")
    values = _INVERSES
    for index in range(len(values), size + 1):
        values.append(-values[MOD % index] * (MOD // index) % MOD)
    return values


def _sparse_terms(series, degree, threshold):
    terms = []
    for index in range(1, min(len(series), degree)):
        value = series[index] % MOD
        if value:
            terms.append((index, value))
            if len(terms) > threshold:
                return None
    return terms


def _fps_inv_sparse(series, degree, first_inverse, terms):
    result = [0] * degree
    result[0] = first_inverse
    for index in range(1, degree):
        total = 0
        for offset, coefficient in terms:
            if offset > index:
                break
            total += coefficient * result[index - offset]
        result[index] = -total * first_inverse % MOD
    return result


def _fps_div_sparse(numerator, degree, first_inverse, terms):
    result = [0] * degree
    for index in range(degree):
        total = numerator[index] % MOD if index < len(numerator) else 0
        for offset, coefficient in terms:
            if offset > index:
                break
            total -= coefficient * result[index - offset]
        result[index] = total * first_inverse % MOD
    return result


def _fps_log_sparse(series, degree, terms):
    inverse = _inverses(degree)
    result = [0] * degree
    for index in range(1, degree):
        total = index * (series[index] % MOD) if index < len(series) else 0
        for offset, coefficient in terms:
            if offset >= index:
                break
            total -= (
                (index - offset) * coefficient * result[index - offset]
            )
        result[index] = total * inverse[index] % MOD
    return result


def _fps_exp_sparse(degree, terms):
    inverse = _inverses(degree)
    result = [0] * degree
    result[0] = 1
    for index in range(1, degree):
        total = 0
        for offset, coefficient in terms:
            if offset > index:
                break
            total += offset * coefficient * result[index - offset]
        result[index] = total * inverse[index] % MOD
    return result


def _fps_power_unit_sparse(degree, exponent, terms):
    inverse = _inverses(degree)
    result = [0] * degree
    result[0] = 1
    exponent %= MOD
    for index in range(1, degree):
        total = 0
        for offset, coefficient in terms:
            if offset > index:
                break
            factor = (exponent * offset - index + offset) % MOD
            total += factor * coefficient * result[index - offset]
        result[index] = total * inverse[index] % MOD
    return result


def shrink(series):
    """係数をmodで正規化し、末尾の0を除いた新しいlistを返す。O(N)。"""

    result = [value % MOD for value in series]
    while result and result[-1] == 0:
        result.pop()
    return result


def fps_add(first, second):
    """2つのFPSを係数ごとに加え、長い方と同じ長さのlistを返す。O(N)。"""

    size = max(len(first), len(second))
    result = [0] * size
    common = min(len(first), len(second))
    mod = MOD
    for index in range(common):
        result[index] = (first[index] + second[index]) % mod
    for index in range(common, len(first)):
        result[index] = first[index] % mod
    for index in range(common, len(second)):
        result[index] = second[index] % mod
    return result


def fps_sub(first, second):
    """`first-second`の係数列を長い方と同じ長さで返す。O(N)。"""

    size = max(len(first), len(second))
    result = [0] * size
    common = min(len(first), len(second))
    mod = MOD
    for index in range(common):
        result[index] = (first[index] - second[index]) % mod
    for index in range(common, len(first)):
        result[index] = first[index] % mod
    for index in range(common, len(second)):
        result[index] = -second[index] % mod
    return result


def fps_neg(series):
    """各係数の加法逆元を同じ長さのlistで返す。O(N)。"""

    return [-value % MOD for value in series]


def fps_diff(series):
    """形式微分の係数を昇べき順で返す。O(N)。"""

    mod = MOD
    return [index * series[index] % mod for index in range(1, len(series))]


def fps_integral(series):
    """定数項を0とした形式積分の係数を昇べき順で返す。O(N)。"""

    inverse = _inverses(len(series))
    mod = MOD
    result = [0] * (len(series) + 1)
    for index, value in enumerate(series, 1):
        result[index] = value * inverse[index] % mod
    return result


def fps_eval(series, value):
    """FPSを多項式とみなし`value`へ代入した値を返す。O(N)。"""

    result = 0
    value %= MOD
    mod = MOD
    for coefficient in reversed(series):
        result = (result * value + coefficient) % mod
    return result


def _inverse_step(series, result, current, target):
    size = current << 1
    mod = MOD
    left = [value % mod for value in series[:target]]
    left.extend([0] * (size - len(left)))
    right = result + [0] * (size - current)
    _butterfly(left)
    _butterfly(right)
    for index in range(size):
        left[index] = left[index] * right[index] % mod
    _intt(left)
    for index in range(current):
        left[index] = 0
    for index in range(current, target):
        left[index] = -left[index] % mod
    for index in range(target, size):
        left[index] = 0
    _butterfly(left)
    for index in range(size):
        left[index] = left[index] * right[index] % mod
    _intt(left)
    result.extend(left[current:target])


def fps_inv(series, degree=None):
    r"""$1/f(x)\bmod x^{degree}$の係数を`degree`個返す。O(N log N)。"""

    degree = _degree(degree, len(series))
    if degree == 0:
        return []
    if not series or series[0] % MOD == 0:
        raise ZeroDivisionError("fps inverse requires nonzero constant coefficient")
    first_inverse = pow(series[0] % MOD, MOD - 2, MOD)
    terms = _sparse_terms(series, degree, _SPARSE_INV_THRESHOLD)
    if terms is not None:
        return _fps_inv_sparse(series, degree, first_inverse, terms)
    result = [first_inverse]
    current = 1
    while current < degree:
        target = min(current << 1, degree)
        _check_length(current << 1)
        _inverse_step(series, result, current, target)
        current = target
    return result


def fps_div(numerator, denominator, degree=None):
    r"""Return ``numerator / denominator mod x^degree``. O(N log N)."""

    degree = _degree(degree, len(numerator))
    if degree == 0:
        return []
    if not denominator or denominator[0] % MOD == 0:
        raise ZeroDivisionError("fps division requires nonzero denominator constant")
    first_inverse = pow(denominator[0] % MOD, MOD - 2, MOD)
    terms = _sparse_terms(
        denominator, degree, _SPARSE_DIV_THRESHOLD
    )
    if terms is not None:
        return _fps_div_sparse(
            numerator, degree, first_inverse, terms
        )
    inverse = fps_inv(denominator, degree)
    result = multiply(numerator[:degree], inverse)[:degree]
    result.extend([0] * (degree - len(result)))
    return result


def fps_log(series, degree=None):
    r"""$\log f(x)\bmod x^{degree}$を返す。`f[0]`は1。O(N log N)。"""

    degree = _degree(degree, len(series))
    if degree == 0:
        return []
    if not series or series[0] % MOD != 1:
        raise ValueError("fps logarithm requires constant coefficient 1")
    terms = _sparse_terms(series, degree, _SPARSE_LOG_THRESHOLD)
    if terms is not None:
        return _fps_log_sparse(series, degree, terms)
    product = multiply(fps_diff(series), fps_inv(series, degree))
    result = fps_integral(product[:degree - 1])
    result.extend([0] * (degree - len(result)))
    return result


def _fps_exp_ntt(series, degree):
    mod = MOD
    b = [1, series[1] % mod if len(series) > 1 else 0]
    c = [1]
    z2 = [1, 1]
    inverse = [0, 1]
    size = 2
    while size < degree:
        doubled = size << 1
        y = b + [0] * size
        _butterfly(y)
        z1 = z2
        z = [y[index] * z1[index] % mod for index in range(size)]
        _intt(z)
        for index in range(size >> 1):
            z[index] = 0
        _butterfly(z)
        for index in range(size):
            z[index] = -z[index] * z1[index] % mod
        _intt(z)
        c.extend(z[size >> 1:])
        z2 = c + [0] * size
        _butterfly(z2)

        source_size = min(len(series), size)
        x = [series[index] % mod for index in range(source_size)]
        x.extend([0] * (size - source_size))
        x = fps_diff(x)
        x.append(0)
        _butterfly(x)
        for index in range(size):
            x[index] = x[index] * y[index] % mod
        _intt(x)
        for index in range(1, len(b)):
            x[index - 1] = (x[index - 1] - index * b[index]) % mod
        x.extend([0] * size)
        for index in range(size - 1):
            x[size + index], x[index] = x[index], 0
        _butterfly(x)
        for index in range(doubled):
            x[index] = x[index] * z2[index] % mod
        _intt(x)
        x.pop()
        for index in range(len(inverse), len(x) + 1):
            inverse.append(-inverse[mod % index] * (mod // index) % mod)
        x = [0] + [
            value * inverse[index + 1] % mod
            for index, value in enumerate(x)
        ]
        for index in range(size):
            x[index] = 0
        for index in range(size, min(len(series), doubled)):
            x[index] = (x[index] + series[index]) % mod
        _butterfly(x)
        for index in range(doubled):
            x[index] = x[index] * y[index] % mod
        _intt(x)
        b.extend(x[size:])
        size = doubled
    return b[:degree]


def fps_exp(series, degree=None):
    r"""$\exp f(x)\bmod x^{degree}$を返す。`f[0]`は0。O(N log N)。"""

    degree = _degree(degree, len(series))
    if degree == 0:
        return []
    if series and series[0] % MOD:
        raise ValueError("fps exponential requires constant coefficient 0")
    terms = _sparse_terms(series, degree, _SPARSE_EXP_THRESHOLD)
    if terms is not None:
        return _fps_exp_sparse(degree, terms)
    _check_length(1 << (degree - 1).bit_length())
    if degree == 1:
        return [1]
    return _fps_exp_ntt(series, degree)


def fps_pow(series, exponent, degree=None):
    r"""$f(x)^{exponent}\bmod x^{degree}$を係数`degree`個で返す。O(N log N)。"""

    degree = _degree(degree, len(series))
    if degree == 0:
        return []
    if exponent == 0:
        return [1] + [0] * (degree - 1)
    leading = 0
    while leading < len(series) and series[leading] % MOD == 0:
        leading += 1
    if leading == len(series):
        if exponent < 0:
            raise ZeroDivisionError("a zero series cannot have negative exponent")
        return [0] * degree
    if exponent < 0 and leading:
        raise ValueError("negative power requires an invertible series")
    shift = leading * exponent
    if shift >= degree:
        return [0] * degree
    coefficient = series[leading] % MOD
    inverse_coefficient = pow(coefficient, MOD - 2, MOD)
    needed = degree - shift
    normalized = [
        value * inverse_coefficient % MOD for value in series[leading:]
    ]
    terms = _sparse_terms(
        normalized, needed, _SPARSE_POWER_THRESHOLD
    )
    if terms is not None:
        result = _fps_power_unit_sparse(needed, exponent, terms)
    else:
        logarithm = fps_log(normalized, needed)
        for index in range(needed):
            logarithm[index] = logarithm[index] * exponent % MOD
        result = fps_exp(logarithm, needed)
    scale = pow(coefficient, exponent, MOD)
    return [0] * shift + [value * scale % MOD for value in result]


def fps_sqrt(series, degree=None):
    r"""$g(x)^2=f(x)\bmod x^{degree}$となる係数列を返し、なければ`None`。O(N log N)。"""

    degree = _degree(degree, len(series))
    if degree == 0:
        return []
    leading = 0
    limit = min(len(series), degree)
    while leading < limit and series[leading] % MOD == 0:
        leading += 1
    if leading == limit:
        return [0] * degree
    if leading & 1:
        return None
    shift = leading >> 1
    needed = degree - shift
    source = [value % MOD for value in series[leading:]]
    root = _mod_sqrt(source[0])
    if root == -1:
        return None
    inverse_constant = pow(source[0], MOD - 2, MOD)
    normalized = [value * inverse_constant % MOD for value in source]
    terms = _sparse_terms(
        normalized, needed, _SPARSE_POWER_THRESHOLD
    )
    if terms is not None:
        result = _fps_power_unit_sparse(
            needed, (MOD + 1) >> 1, terms
        )
        return [0] * shift + [value * root % MOD for value in result]
    inverse_two = (MOD + 1) >> 1
    result = [root]
    current = 1
    while current < needed:
        target = min(current << 1, needed)
        quotient = multiply(source[:target], fps_inv(result, target))[:target]
        result.extend([0] * (target - len(result)))
        for index in range(target):
            value = quotient[index] if index < len(quotient) else 0
            result[index] = (result[index] + value) * inverse_two % MOD
        current = target
    return [0] * shift + result[:needed]


def taylor_shift(series, shift):
    """$f(x+shift)$の係数を`f`と同じ長さのlistで返す。O(N log N)。"""

    size = len(series)
    if size == 0:
        return []
    factorial = [1] * size
    for index in range(1, size):
        factorial[index] = factorial[index - 1] * index % MOD
    inverse_factorial = [0] * size
    inverse_factorial[-1] = pow(factorial[-1], MOD - 2, MOD)
    for index in range(size - 1, 0, -1):
        inverse_factorial[index - 1] = inverse_factorial[index] * index % MOD
    left = [series[index] * factorial[index] % MOD for index in range(size)]
    left.reverse()
    right = [0] * size
    power = 1
    shift %= MOD
    for index in range(size):
        right[index] = power * inverse_factorial[index] % MOD
        power = power * shift % MOD
    product = multiply(left, right)
    return [
        product[size - 1 - index] * inverse_factorial[index] % MOD
        for index in range(size)
    ]


def fps_product(polynomials):
    """複数の多項式をすべて掛けた係数列を返す。O(S log S log K)。"""

    heap = []
    serial = 0
    for polynomial in polynomials:
        values = [value % MOD for value in polynomial]
        if not values:
            return []
        heap.append((len(values), serial, values))
        serial += 1
    if not heap:
        return [1]
    heapify(heap)
    while len(heap) > 1:
        _, _, first = heappop(heap)
        _, _, second = heappop(heap)
        product = multiply(first, second)
        heappush(heap, (len(product), serial, product))
        serial += 1
    return heap[0][2]

"""998244353上で線形漸化式の推定と巨大添字の項を計算する。

Berlekamp--Masseyで最短漸化式を求め、Bostan--Moriで有理FPS
`P(x)/Q(x)`の指定係数を計算する。
"""

from library_codex.convolution.NTT998 import MOD, _butterfly, _intt, multiply
from library_codex.fps998.FPS import shrink
from library_codex.polynomial.PolynomialDivision998 import poly_divmod


def _bostan_mori_step(numerator, denominator, parity):
    numerator_size = len(numerator)
    denominator_size = len(denominator)
    if min(numerator_size, denominator_size) <= 60:
        opposite = denominator[:]
        for position in range(1, denominator_size, 2):
            opposite[position] = -opposite[position] % MOD
        multiplied_numerator = multiply(numerator, opposite)
        multiplied_denominator = multiply(denominator, opposite)
        return (
            multiplied_numerator[parity::2],
            multiplied_denominator[::2],
        )

    numerator_output_size = numerator_size + denominator_size - 1
    denominator_output_size = denominator_size * 2 - 1
    size = 1 << (
        max(numerator_output_size, denominator_output_size) - 1
    ).bit_length()
    frequency_p = [value % MOD for value in numerator]
    frequency_q = [value % MOD for value in denominator]
    frequency_p.extend([0] * (size - numerator_size))
    frequency_q.extend([0] * (size - denominator_size))
    _butterfly(frequency_p)
    _butterfly(frequency_q)
    reduced_q = [0] * (size >> 1)
    for position in range(0, size, 2):
        frequency_q[position], frequency_q[position + 1] = (
            frequency_q[position + 1],
            frequency_q[position],
        )
        frequency_p[position] = (
            frequency_p[position] * frequency_q[position]
        ) % MOD
        frequency_p[position + 1] = (
            frequency_p[position + 1] * frequency_q[position + 1]
        ) % MOD
        reduced_q[position >> 1] = (
            frequency_q[position] * frequency_q[position + 1]
        ) % MOD
    _intt(frequency_p)
    _intt(reduced_q)
    return (
        frequency_p[parity:numerator_output_size:2],
        reduced_q[:denominator_size],
    )


def berlekamp_massey(sequence):
    """先頭から与えた列を生成する最短線形漸化式の係数を返す。O(N^2)。"""

    connection = [1]
    previous = [1]
    length = 0
    shift = 1
    previous_discrepancy = 1
    for position, raw_value in enumerate(sequence):
        discrepancy = raw_value % MOD
        for index in range(1, length + 1):
            discrepancy += connection[index] * sequence[position - index]
        discrepancy %= MOD
        if discrepancy == 0:
            shift += 1
            continue
        scale = discrepancy * pow(previous_discrepancy, MOD - 2, MOD) % MOD
        saved = connection[:]
        required = len(previous) + shift
        if len(connection) < required:
            connection.extend([0] * (required - len(connection)))
        for index, value in enumerate(previous):
            connection[index + shift] = (
                connection[index + shift] - scale * value
            ) % MOD
        if length * 2 <= position:
            length = position + 1 - length
            previous = saved
            previous_discrepancy = discrepancy
            shift = 1
        else:
            shift += 1
    return [-connection[index] % MOD for index in range(1, length + 1)]


def bostan_mori(index, numerator, denominator):
    """有理FPS`numerator/denominator`の`x^index`係数を返す。O(K log K log N)。"""

    if index < 0:
        raise ValueError("index must be nonnegative")
    denominator = shrink(denominator)
    if not denominator or denominator[0] == 0:
        raise ZeroDivisionError("denominator requires nonzero constant coefficient")
    numerator = shrink(numerator)
    polynomial_part = 0
    if len(numerator) >= len(denominator):
        quotient, numerator = poly_divmod(numerator, denominator)
        if index < len(quotient):
            polynomial_part = quotient[index]
    if not numerator:
        return polynomial_part
    while index:
        numerator, denominator = _bostan_mori_step(
            numerator,
            denominator,
            index & 1,
        )
        index >>= 1
        if not numerator:
            return polynomial_part
    return (
        polynomial_part
        + numerator[0] * pow(denominator[0], MOD - 2, MOD)
    ) % MOD


def linear_recurrence_nth(initial, coefficients, index):
    """`a[n]=sum(coefficients[i]*a[n-1-i])`で定まる`a[index]`を返す。O(K log K log N)。"""

    if index < 0:
        raise ValueError("index must be nonnegative")
    order = len(coefficients)
    if index < len(initial):
        return initial[index] % MOD
    if order == 0:
        return 0
    if len(initial) < order:
        raise ValueError("at least order initial values are required")
    denominator = [1] + [-value % MOD for value in coefficients]
    numerator = multiply(initial[:order], denominator)[:order]
    return bostan_mori(index, numerator, denominator)


def nth_term(index, sequence):
    """与えた列から漸化式を推定し、`index`番目の値を返す。O(N^2+K log K log index)。"""

    if index < 0:
        raise ValueError("index must be nonnegative")
    if index < len(sequence):
        return sequence[index] % MOD
    coefficients = berlekamp_massey(sequence)
    if not coefficients:
        return 0
    return linear_recurrence_nth(sequence, coefficients, index)

"""998244353上の2次元NTTと2変数係数畳み込み。

行列`values[i][j]`を$x^i y^j$の係数として扱う。`ntt2d`と`intt2d`は
各辺長が2の冪である長方形listを破壊的に変換する。
"""

from library_codex.convolution.NTT998 import MOD, intt, ntt


def _shape(matrix):
    rows = len(matrix)
    if rows == 0:
        return 0, 0
    columns = len(matrix[0])
    if columns == 0:
        raise ValueError("matrix rows must be nonempty")
    for row in matrix:
        if len(row) != columns:
            raise ValueError("matrix must be rectangular")
    return rows, columns


def ntt2d(values):
    """2次元係数行列を破壊的に順変換し、同じ2次元listを返す。O(RC(log R+log C))。"""

    rows, columns = _shape(values)
    if rows == 0:
        return values
    for row in values:
        ntt(row)
    column = [0] * rows
    for index in range(columns):
        for row in range(rows):
            column[row] = values[row][index]
        ntt(column)
        for row in range(rows):
            values[row][index] = column[row]
    return values


def intt2d(values):
    """2次元周波数行列を破壊的に正規化済み逆変換して返す。O(RC(log R+log C))。"""

    rows, columns = _shape(values)
    if rows == 0:
        return values
    for row in values:
        intt(row)
    column = [0] * rows
    for index in range(columns):
        for row in range(rows):
            column[row] = values[row][index]
        intt(column)
        for row in range(rows):
            values[row][index] = column[row]
    return values


def multiply2d(first, second):
    r"""2つの2変数係数行列の積を`(R1+R2-1)x(C1+C2-1)`で返す。O(RC(log R+log C))。"""

    first_rows, first_columns = _shape(first)
    second_rows, second_columns = _shape(second)
    if first_rows == 0 or second_rows == 0:
        return []
    output_rows = first_rows + second_rows - 1
    output_columns = first_columns + second_columns - 1
    rows = 1 << (output_rows - 1).bit_length()
    columns = 1 << (output_columns - 1).bit_length()
    left = [[0] * columns for _ in range(rows)]
    right = [[0] * columns for _ in range(rows)]
    for row in range(first_rows):
        for column in range(first_columns):
            left[row][column] = first[row][column] % MOD
    for row in range(second_rows):
        for column in range(second_columns):
            right[row][column] = second[row][column] % MOD
    ntt2d(left)
    ntt2d(right)
    for row in range(rows):
        left_row = left[row]
        right_row = right[row]
        for column in range(columns):
            left_row[column] = left_row[column] * right_row[column] % MOD
    intt2d(left)
    return [row[:output_columns] for row in left[:output_rows]]

"""998244353上で部分集合・多重集合の重さ別個数を母関数から求める。

`counts[w]`を重さ`w`の種類数とし、返り値`result[s]`は総重さ`s`に
なる選び方の個数を表す。返す長さは`len(counts)`。
"""

from library_codex.convolution.NTT998 import MOD
from library_codex.fps998.FPS import fps_exp


_INVERSES = [0, 1]


def _extend_inverses(size):
    values = _INVERSES
    for index in range(len(values), size):
        values.append(-values[MOD % index] * (MOD // index) % MOD)
    return values


def subset_sum(counts):
    r"""`prod_(w>=1)(1+x^w)^counts[w]`の先頭`len(counts)`係数を返す。O(N log N)。"""

    size = len(counts)
    if size == 0:
        return []
    inverse = _extend_inverses(size)
    logarithm = [0] * size
    for weight in range(1, size):
        count = counts[weight] % MOD
        if count == 0:
            continue
        scaled = count * weight
        quotient = 1
        for total in range(weight, size, weight):
            value = scaled * inverse[total] % MOD
            if quotient & 1:
                logarithm[total] += value
            else:
                logarithm[total] -= value
            quotient += 1
    return fps_exp([value % MOD for value in logarithm], size)


def multiset_sum(counts):
    r"""`prod_(w>=1)(1-x^w)^(-counts[w])`の先頭`len(counts)`係数を返す。O(N log N)。"""

    size = len(counts)
    if size == 0:
        return []
    inverse = _extend_inverses(size)
    logarithm = [0] * size
    for weight in range(1, size):
        count = counts[weight] % MOD
        if count == 0:
            continue
        scaled = count * weight
        for total in range(weight, size, weight):
            logarithm[total] += scaled * inverse[total] % MOD
    return fps_exp([value % MOD for value in logarithm], size)

