    for index in range(1, size):
        factorial[index] = factorial[index - 1] * index % mod
    try:
        inverse_factorial = [0] * size
        inverse_factorial[-1] = pow(factorial[-1], -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('factorial is not invertible') from error
    for index in range(size - 1, 0, -1):
        inverse_factorial[index - 1] = inverse_factorial[index] * index % mod
    left = [series[index] * factorial[index] % mod for index in range(size)]
    left.reverse()
    right = [0] * size
    power = 1
    shift %= mod
    for index in range(size):
        right[index] = power * inverse_factorial[index] % mod
        power = power * shift % mod
    product = fps_multiply(left, right, mod)
    return [product[size - 1 - index] * inverse_factorial[index] % mod for index in range(size)]

def fps_product(polynomials, mod=DEFAULT_MOD):
    """Multiply many polynomials by repeatedly combining the shortest pair. O(S log S log K)."""
    heap = []
    serial = 0
    for polynomial in polynomials:
        values = [value % mod for value in polynomial]
        if not values:
            return []
        heap.append((len(values), serial, values))
        serial += 1
    if not heap:
        return [1]
    heapify(heap)
    while len(heap) > 1:
        _, _, first = heappop(heap)
        _, _, second = heappop(heap)
        product = fps_multiply(first, second, mod)
        heappush(heap, (len(product), serial, product))
        serial += 1
    return heap[0][2]
fps_sub = fps_subtract
fps_neg = fps_negate
fps_mul = fps_multiply
fps_diff = fps_derivative
fps_inv = fps_inverse
fps_log = fps_logarithm
fps_exp = fps_exponential
fps_pow = fps_power
fps_sqrt = fps_square_root
fps_eval = fps_evaluate
tayler_shift = fps_taylor_shift

# 本体
"""形式的冪級数の分子と分母を保ったまま四則演算する。"""

class FPSFraction:
    __slots__ = ('numerator', 'denominator', 'mod')

    def __init__(self, numerator=None, denominator=None, mod=DEFAULT_MOD):
        self.mod = mod
        self.numerator = [0] if numerator is None else list(numerator)
        self.denominator = [1] if denominator is None else list(denominator)
        if not fps_shrink(self.denominator, mod):
            raise ZeroDivisionError('the denominator polynomial is zero')
    p = property(lambda self: self.numerator)
    q = property(lambda self: self.denominator)

    def _coerce(self, other):
        if isinstance(other, FPSFraction):
            if self.mod != other.mod:
                raise ValueError('moduli differ')
            return other
        return FPSFraction([other], [1], self.mod)

    def __add__(self, other):
        other = self._coerce(other)
        return FPSFraction(fps_add(fps_multiply(self.numerator, other.denominator, self.mod), fps_multiply(other.numerator, self.denominator, self.mod), self.mod), fps_multiply(self.denominator, other.denominator, self.mod), self.mod)
    __radd__ = __add__

    def __neg__(self):
        return FPSFraction([-value % self.mod for value in self.numerator], self.denominator, self.mod)

    def __sub__(self, other):
        return self + -self._coerce(other)

    def __rsub__(self, other):
        return self._coerce(other) - self

    def __mul__(self, other):
        other = self._coerce(other)
        return FPSFraction(fps_multiply(self.numerator, other.numerator, self.mod), fps_multiply(self.denominator, other.denominator, self.mod), self.mod)
    __rmul__ = __mul__

    def __truediv__(self, other):
        return self * self._coerce(other).inverse()

    def __rtruediv__(self, other):
        return self._coerce(other) / self

    def inverse(self):
        if not fps_shrink(self.numerator, self.mod):
            raise ZeroDivisionError('the zero fraction is not invertible')
        return FPSFraction(self.denominator, self.numerator, self.mod)

    def shrink(self):
        self.numerator = fps_shrink(self.numerator, self.mod)
        self.denominator = fps_shrink(self.denominator, self.mod)
        return self

