        return [1] + [0] * (degree - 1)
    leading = 0
    while leading < len(series) and series[leading] % mod == 0:
        leading += 1
    if leading == len(series):
        if exponent < 0:
            raise ZeroDivisionError('a zero series cannot have negative exponent')
        return [0] * degree
    if exponent < 0 and leading:
        raise ValueError('negative power requires an invertible series')
    shift = leading * exponent
    if shift >= degree:
        return [0] * degree
    coefficient = series[leading] % mod
    try:
        inverse_coefficient = pow(coefficient, -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('the leading coefficient is not invertible') from error
    needed = degree - shift
    normalized = [value * inverse_coefficient % mod for value in series[leading:]]
    terms = _fps_formal_power_series_sparse_terms(normalized, needed, mod, _fps_formal_power_series_SPARSE_POWER_THRESHOLD)
    if terms is not None:
        result = _fps_formal_power_series_fps_power_unit_sparse(needed, exponent, terms, mod)
    else:
        logarithm = fps_logarithm(normalized, needed, mod)
        for index in range(needed):
            logarithm[index] = logarithm[index] * exponent % mod
        result = fps_exponential(logarithm, needed, mod)
    scale = pow(coefficient, exponent, mod)
    result = [value * scale % mod for value in result]
    return [0] * shift + result

def fps_square_root(series, degree=None, mod=DEFAULT_MOD):
    """Return one formal square root, or None when no root exists. O(N log N)."""
    degree = _fps_formal_power_series_degree(degree, len(series))
    if degree == 0:
        return []
    leading = 0
    limit = min(len(series), degree)
    while leading < limit and series[leading] % mod == 0:
        leading += 1
    if leading == limit:
        return [0] * degree
    if leading & 1:
        return None
    shift = leading >> 1
    needed = degree - shift
    source = [value % mod for value in series[leading:]]
    root = modular_square_root(source[0], mod)
    if root == -1:
        return None
    try:
        inverse_two = pow(2, -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('fps square root requires invertible 2') from error
    inverse_constant = pow(source[0], -1, mod)
    normalized = [value * inverse_constant % mod for value in source]
    terms = _fps_formal_power_series_sparse_terms(normalized, needed, mod, _fps_formal_power_series_SPARSE_POWER_THRESHOLD)
    if terms is not None:
        result = _fps_formal_power_series_fps_power_unit_sparse(needed, inverse_two, terms, mod)
        return [0] * shift + [value * root % mod for value in result]
    result = [root]
    current = 1
    while current < needed:
        target = min(current << 1, needed)
        quotient = fps_multiply(source[:target], fps_inverse(result, target, mod), mod)[:target]
        result.extend([0] * (target - len(result)))
        for index in range(target):
            value = quotient[index] if index < len(quotient) else 0
            result[index] = (result[index] + value) * inverse_two % mod
        current = target
    return [0] * shift + result[:needed]

def fps_taylor_shift(series, shift, mod=DEFAULT_MOD):
    """Return coefficients of ``f(x + shift)``. O(N log N)."""
    size = len(series)
    if size == 0:
        return []
    _fps_formal_power_series_inverses(size, mod)
    factorial = [1] * size
    for index in range(1, size):
        factorial[index] = factorial[index - 1] * index % mod
    try:
        inverse_factorial = [0] * size
        inverse_factorial[-1] = pow(factorial[-1], -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('factorial is not invertible') from error
    for index in range(size - 1, 0, -1):
        inverse_factorial[index - 1] = inverse_factorial[index] * index % mod
    left = [series[index] * factorial[index] % mod for index in range(size)]
    left.reverse()
    right = [0] * size
    power = 1
    shift %= mod
    for index in range(size):
        right[index] = power * inverse_factorial[index] % mod
        power = power * shift % mod
    product = fps_multiply(left, right, mod)
    return [product[size - 1 - index] * inverse_factorial[index] % mod for index in range(size)]

def fps_product(polynomials, mod=DEFAULT_MOD):
    """Multiply many polynomials by repeatedly combining the shortest pair. O(S log S log K)."""
    heap = []
    serial = 0
    for polynomial in polynomials:
        values = [value % mod for value in polynomial]
        if not values:
            return []
        heap.append((len(values), serial, values))
        serial += 1
    if not heap:
        return [1]
    heapify(heap)
    while len(heap) > 1:
        _, _, first = heappop(heap)
        _, _, second = heappop(heap)
        product = fps_multiply(first, second, mod)
        heappush(heap, (len(product), serial, product))
        serial += 1
    return heap[0][2]
fps_sub = fps_subtract
fps_neg = fps_negate
fps_mul = fps_multiply
fps_diff = fps_derivative
fps_inv = fps_inverse
fps_log = fps_logarithm
fps_exp = fps_exponential
fps_pow = fps_power
fps_sqrt = fps_square_root
fps_eval = fps_evaluate
tayler_shift = fps_taylor_shift

# 依存: polynomial/PolynomialDivision.py
"""Polynomial quotient and remainder in ascending coefficient order."""

def poly_div(dividend, divisor, mod=DEFAULT_MOD):
    """Return the polynomial quotient. O(N log N)."""
    first = fps_shrink(dividend, mod)
    second = fps_shrink(divisor, mod)
    if not second:
        raise ZeroDivisionError('polynomial division by zero')
    if len(first) < len(second):
        return []
    quotient_size = len(first) - len(second) + 1
    if len(second) <= 64:
        result = [0] * quotient_size
        remainder = first[:]
        try:
            inverse_leading = pow(second[-1], -1, mod)
        except ValueError as error:
            raise ZeroDivisionError('the leading coefficient is not invertible') from error
        width = len(second)
        for index in range(quotient_size - 1, -1, -1):
            value = remainder[index + width - 1] * inverse_leading % mod
            result[index] = value
            for offset in range(width):
                remainder[index + offset] = (remainder[index + offset] - value * second[offset]) % mod
        return result
    reversed_dividend = list(reversed(first[-quotient_size:]))
    reversed_divisor = list(reversed(second))
    result = fps_multiply(reversed_dividend, fps_inverse(reversed_divisor, quotient_size, mod), mod)[:quotient_size]
    result.reverse()
    return result

def poly_divmod(dividend, divisor, mod=DEFAULT_MOD):
    """Return ``(quotient, remainder)`` for polynomial division. O(N log N)."""
    second = fps_shrink(divisor, mod)
    if not second:
        raise ZeroDivisionError('polynomial division by zero')
    first = fps_shrink(dividend, mod)
    quotient = poly_div(first, second, mod)
    if not quotient:
        return ([], first)
    product = fps_multiply(quotient, second, mod)
    remainder = [0] * min(len(second) - 1, max(len(first), len(product)))
    for index in range(len(remainder)):
        left = first[index] if index < len(first) else 0
        right = product[index] if index < len(product) else 0
        remainder[index] = (left - right) % mod
    while remainder and remainder[-1] == 0:
        remainder.pop()
    return (quotient, remainder)

def poly_mod(dividend, divisor, mod=DEFAULT_MOD):
    """Return the remainder of polynomial division. O(N log N)."""
    return poly_divmod(dividend, divisor, mod)[1]

# 依存: polynomial/MultipointEvaluation.py
def _polynomial_multipoint_evaluation_batch_inverse(values, mod):
    size = len(values)
    prefix = [1] * (size + 1)
    for index, value in enumerate(values):
        value %= mod
        if value == 0:
            raise ValueError('interpolation points must be distinct modulo mod')
        prefix[index + 1] = prefix[index] * value % mod
    try:
        inverse = pow(prefix[-1], -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('interpolation requires a field') from error
    result = [0] * size
    for index in range(size - 1, -1, -1):
        result[index] = inverse * prefix[index] % mod
        inverse = inverse * (values[index] % mod) % mod
    return result

class ProductTree:
    __slots__ = ('points', 'mod', 'n', 'size', 'products')

    def __init__(self, points, mod=DEFAULT_MOD):
        self.mod = mod
        self.points = [value % mod for value in points]
        self.n = len(self.points)
        size = 1
        while size < self.n:
            size <<= 1
        self.size = size
        products = [None] * (size << 1)
        for index, value in enumerate(self.points):
            products[size + index] = [-value % mod, 1]
        for node in range(size - 1, 0, -1):
            left = products[node << 1]
            right = products[node << 1 | 1]
            if left is None:
                products[node] = right
            elif right is None:
                products[node] = left
            else:
                products[node] = fps_multiply(left, right, mod)
        self.products = products

    @property
    def polynomial(self):
        if self.n == 0:
            return [1]
        return self.products[1][:]

    def evaluate(self, polynomial, direct_threshold=64):
        if direct_threshold < 1:
            raise ValueError('direct_threshold must be positive')
        if self.n == 0:
            return []
        mod = self.mod
        current = fps_shrink(polynomial, mod)
        if not current:
            return [0] * self.n
        root = self.products[1]
        if len(current) >= len(root):
            current = poly_mod(current, root, mod)
            if not current:
                return [0] * self.n
        result = [0] * self.n
        stack = [(1, 0, self.size, current)]
        points = self.points
        products = self.products
        limit = self.n
        while stack:
            node, left, right, values = stack.pop()
            active_right = min(right, limit)
            if left >= active_right:
                continue
            if active_right - left <= direct_threshold or len(values) <= direct_threshold:
                for point_index in range(left, active_right):
                    value = 0
                    point = points[point_index]
                    for coefficient in reversed(values):
                        value = (value * point + coefficient) % mod
                    result[point_index] = value
                continue
            middle = left + right >> 1
            right_node = node << 1 | 1
            right_product = products[right_node]
            if right_product is not None and middle < limit:
                if len(values) < len(right_product):
                    right_values = values
                else:
                    right_values = poly_mod(values, right_product, mod)
                stack.append((right_node, middle, right, right_values))
            left_node = node << 1
            left_product = products[left_node]
            if len(values) < len(left_product):
                left_values = values
            else:
                left_values = poly_mod(values, left_product, mod)
            stack.append((left_node, left, middle, left_values))
        return result

    def interpolate(self, values):
        if len(values) != self.n:
            raise ValueError('points and values must have the same length')
        if self.n == 0:
            return []
        mod = self.mod
        derivative_values = self.evaluate(fps_derivative(self.products[1], mod))
        inverse_values = _polynomial_multipoint_evaluation_batch_inverse(derivative_values, mod)
        coefficients = [None] * (self.size << 1)
        for index, value in enumerate(values):
            coefficients[self.size + index] = [value * inverse_values[index] % mod]
        products = self.products
        for node in range(self.size - 1, 0, -1):
            left_node = node << 1
            right_node = left_node | 1
            left = coefficients[left_node]
            right = coefficients[right_node]
            if left is None:
                coefficients[node] = right
            elif right is None:
                coefficients[node] = left
            else:
                coefficients[node] = fps_add(fps_multiply(left, products[right_node], mod), fps_multiply(right, products[left_node], mod), mod)
        result = coefficients[1]
        result.extend([0] * (self.n - len(result)))
        return result[:self.n]

def multipoint_evaluation(polynomial, points, mod=DEFAULT_MOD):
    return ProductTree(points, mod).evaluate(polynomial)

def polynomial_interpolation(points, values, mod=DEFAULT_MOD):
    return ProductTree(points, mod).interpolate(values)

def interpolate_consecutive(values, point, mod=DEFAULT_MOD):
    size = len(values)
    if size == 0:
        raise ValueError('at least one value is required')
    if size > mod:
        raise ValueError('the number of points must not exceed mod')
    point %= mod
    if point < size:
        return values[point] % mod
    left = [1] * (size + 1)
    right = [1] * (size + 1)
    for index in range(size):
        left[index + 1] = left[index] * (point - index) % mod
    for index in range(size - 1, -1, -1):
        right[index] = right[index + 1] * (point - index) % mod
    factorial = 1
    for index in range(2, size):
        factorial = factorial * index % mod
    try:
        inverse_factorial = pow(factorial, -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('interpolation requires a field') from error
    inverse_factorials = [1] * size
    if size > 1:
        inverse_factorials[-1] = inverse_factorial
        for index in range(size - 1, 0, -1):
            inverse_factorials[index - 1] = inverse_factorials[index] * index % mod
    result = 0
    last = size - 1
    for index, value in enumerate(values):
        term = value * left[index] * right[index + 1] * inverse_factorials[index] * inverse_factorials[last - index] % mod
        if last - index & 1:
            result -= term
        else:
            result += term
    return result % mod

def _polynomial_multipoint_evaluation_sample_point_shift_segment(values, point, count, mod):
    degree = len(values) - 1
    factorial = 1
    for index in range(2, degree + 1):
        factorial = factorial * index % mod
    inverse_factorial = [1] * (degree + 1)
    if degree:
        inverse_factorial[-1] = pow(factorial, -1, mod)
        for index in range(degree, 0, -1):
            inverse_factorial[index - 1] = inverse_factorial[index] * index % mod
    weighted = [0] * (degree + 1)
    for index, value in enumerate(values):
        weighted[index] = value * inverse_factorial[index] * inverse_factorial[degree - index] % mod
        if degree - index & 1:
            weighted[index] = -weighted[index] % mod
    reciprocals = [0] * (count + degree)
    for index in range(len(reciprocals)):
        reciprocals[index] = pow(point - degree + index, -1, mod)
    product = fps_multiply(weighted, reciprocals, mod)
    falling = point % mod
    for index in range(1, degree + 1):
        falling = falling * (point - index) % mod
    result = [0] * count
    for index in range(count):
        result[index] = falling * product[degree + index] % mod
        falling = falling * (point + index + 1) % mod
        falling = falling * reciprocals[index] % mod
    return result

def sample_point_shift(values, point, count=None, mod=DEFAULT_MOD):
    if not values:
        raise ValueError('at least one sample is required')
    if count is None:
        count = len(values)
    if count < 0:
        raise ValueError('count must be nonnegative')
    if len(values) > mod:
        raise ValueError('the number of samples must not exceed mod')
    if count == 0:
        return []
    degree = len(values) - 1
    current = point % mod
    remaining = count
    result = []
    while remaining:
        segment = min(remaining, mod - current)
        if current <= degree:
            copied = min(segment, degree - current + 1)
            result.extend((value % mod for value in values[current:current + copied]))
            current += copied
            remaining -= copied
            segment -= copied
            if remaining == 0:
                break
            if current == mod:
                current = 0
                continue
        if segment:
            result.extend(_polynomial_multipoint_evaluation_sample_point_shift_segment(values, current, segment, mod))
            current += segment
            remaining -= segment
        if current == mod:
            current = 0
    return result
MultipointEvaluation = multipoint_evaluation
PolynomialInterpolation = polynomial_interpolation
Interpolate = interpolate_consecutive
SamplePointShift = sample_point_shift

# 依存: combinatorics/Combination.py
"""階乗表を使うCombと、小さいk向けの乗法式で二項係数を計算する。"""
_combinatorics_combination_DEFAULT_MOD = 998244353

class Comb:
    """素数mod上の階乗表を必要なところまで自動で拡張する。"""
    __slots__ = ('mod', 'factorial', 'inverse_factorial')

    def __init__(self, size=0, mod=_combinatorics_combination_DEFAULT_MOD):
        """0からsizeまでの階乗表を構築する。O(size)。"""
        self.mod = mod
        self.factorial = [1]
        self.inverse_factorial = [1]
        self.ensure(size)

    def ensure(self, size):
        """階乗表と逆階乗表をsizeまで拡張する。"""
        old = len(self.factorial) - 1
        if size <= old:
            return
        mod = self.mod
        self.factorial.extend([1] * (size - old))
        for value in range(old + 1, size + 1):
            self.factorial[value] = self.factorial[value - 1] * value % mod
        self.inverse_factorial.extend([1] * (size - old))
        self.inverse_factorial[size] = pow(self.factorial[size], -1, mod)
        for value in range(size, old + 1, -1):
            self.inverse_factorial[value - 1] = self.inverse_factorial[value] * value % mod

    def fact(self, n):
        """n!をmodで割った余りを返す。O(1)、表の拡張時は償却O(n)。"""
        self.ensure(n)
        return self.factorial[n]

    def C(self, n, k):
        """二項係数C(n, k)を返す。O(1)、表の拡張時は償却O(n)。"""
        if k < 0 or n < k or n < 0:
            return 0
        self.ensure(n)
        return self.factorial[n] * self.inverse_factorial[k] % self.mod * self.inverse_factorial[n - k] % self.mod

    def __call__(self, n, k):
        """C(n, k)を返す。O(1)、表の拡張時は償却O(n)。"""
        return self.C(n, k)

    def P(self, n, k):
        """順列数P(n, k)を返す。O(1)、表の拡張時は償却O(n)。"""
        if k < 0 or n < k or n < 0:
            return 0
        self.ensure(n)
        return self.factorial[n] * self.inverse_factorial[n - k] % self.mod

    def H(self, n, k):
        """n種類から重複を許してk個選ぶ重複組合せH(n, k)を返す。O(1)。"""
        if n == 0:
            return int(k == 0)
        return self.C(n + k - 1, k)

def comb_small_k(n, k, mod=_combinatorics_combination_DEFAULT_MOD):
    """nが大きくkが小さいときに二項係数C(n, k)を乗法式で求める。

    O(min(k, n-k))。1からmin(k, n-k)までがmodで可逆である必要がある。
    """
    if k < 0 or n < k:
        return 0
    k = min(k, n - k)
    numerator = denominator = 1
    for i in range(1, k + 1):
        numerator = numerator * (n - k + i) % mod
        denominator = denominator * i % mod
    return numerator * pow(denominator, -1, mod) % mod

# 本体
"""多項式と指数関数の積の有限和・極限和を計算する。"""

def limit_sum_polynomial_exponential(values, ratio, mod=DEFAULT_MOD):
    """Sum ratio**k*f(k), k >= 0, from consecutive samples of f."""
    if not values:
        raise ValueError('at least one sample is required')
    ratio %= mod
    if ratio == 1:
        raise ValueError('the infinite formal sum requires ratio != 1')
    degree = len(values) - 1
    combination = Comb(degree + 1, mod)
    powers = [1] * (degree + 1)
    for index in range(degree):
        powers[index + 1] = powers[index] * ratio % mod
    accumulated = 0
    answer = 0
    for index in range(degree + 1):
        accumulated = (accumulated + powers[index] * values[index]) % mod
        term = combination.C(degree + 1, index + 1) * powers[degree - index] % mod * accumulated % mod
        answer += -term if degree - index & 1 else term
    return answer % mod * pow(pow(1 - ratio, degree + 1, mod), -1, mod) % mod

def sum_polynomial_exponential(values, ratio, count, mod=DEFAULT_MOD):
    """Sum ratio**k*f(k), 0 <= k < count, from consecutive samples of f."""
    if not values:
        raise ValueError('at least one sample is required')
    if count <= 0:
        return 0
    ratio %= mod
    degree = len(values) - 1
    powers = [1] * (degree + 1)
    prefixes = [0] * (degree + 1)
    for index in range(degree + 1):
        if index:
            powers[index] = powers[index - 1] * ratio % mod
        prefixes[index] = powers[index] * values[index] % mod
        if index:
            prefixes[index] = (prefixes[index] + prefixes[index - 1]) % mod
    last = count - 1
    if ratio == 0:
        return values[0] % mod
    if ratio == 1:
        return interpolate_consecutive(prefixes, last, mod)
    combination = Comb(degree + 1, mod)
    constant = 0
    for index in range(degree + 1):
        term = combination.C(degree + 1, index + 1) * powers[degree - index] % mod * prefixes[index] % mod
        constant += -term if degree - index & 1 else term
    constant %= mod
    constant = constant * pow(pow(1 - ratio, degree + 1, mod), -1, mod) % mod
    inverse_ratio = pow(ratio, -1, mod)
    inverse_power = 1
    adjusted = [0] * (degree + 1)
    for index in range(degree + 1):
        adjusted[index] = (prefixes[index] - constant) * inverse_power % mod
        inverse_power = inverse_power * inverse_ratio % mod
    return (pow(ratio, last, mod) * interpolate_consecutive(adjusted, last, mod) + constant) % mod

