# 依存: polynomial/PolynomialDivision.py
"""Polynomial quotient and remainder in ascending coefficient order."""

def poly_div(dividend, divisor, mod=DEFAULT_MOD):
    """Return the polynomial quotient. O(N log N)."""
    first = fps_shrink(dividend, mod)
    second = fps_shrink(divisor, mod)
    if not second:
        raise ZeroDivisionError('polynomial division by zero')
    if len(first) < len(second):
        return []
    quotient_size = len(first) - len(second) + 1
    if len(second) <= 64:
        result = [0] * quotient_size
        remainder = first[:]
        try:
            inverse_leading = pow(second[-1], -1, mod)
        except ValueError as error:
            raise ZeroDivisionError('the leading coefficient is not invertible') from error
        width = len(second)
        for index in range(quotient_size - 1, -1, -1):
            value = remainder[index + width - 1] * inverse_leading % mod
            result[index] = value
            for offset in range(width):
                remainder[index + offset] = (remainder[index + offset] - value * second[offset]) % mod
        return result
    reversed_dividend = list(reversed(first[-quotient_size:]))
    reversed_divisor = list(reversed(second))
    result = fps_multiply(reversed_dividend, fps_inverse(reversed_divisor, quotient_size, mod), mod)[:quotient_size]
    result.reverse()
    return result

def poly_divmod(dividend, divisor, mod=DEFAULT_MOD):
    """Return ``(quotient, remainder)`` for polynomial division. O(N log N)."""
    second = fps_shrink(divisor, mod)
    if not second:
        raise ZeroDivisionError('polynomial division by zero')
    first = fps_shrink(dividend, mod)
    quotient = poly_div(first, second, mod)
    if not quotient:
        return ([], first)
    product = fps_multiply(quotient, second, mod)
    remainder = [0] * min(len(second) - 1, max(len(first), len(product)))
    for index in range(len(remainder)):
        left = first[index] if index < len(first) else 0
        right = product[index] if index < len(product) else 0
        remainder[index] = (left - right) % mod
    while remainder and remainder[-1] == 0:
        remainder.pop()
    return (quotient, remainder)

def poly_mod(dividend, divisor, mod=DEFAULT_MOD):
    """Return the remainder of polynomial division. O(N log N)."""
    return poly_divmod(dividend, divisor, mod)[1]

# 依存: polynomial/PolynomialGCD.py
"""多項式のmonic化・gcd・拡張gcdを計算する。"""

def polynomial_monic(polynomial, mod=DEFAULT_MOD):
    result = fps_shrink(polynomial, mod)
    if not result:
        return []
    inverse = pow(result[-1], -1, mod)
    return [value * inverse % mod for value in result]

def polynomial_gcd(first, second, mod=DEFAULT_MOD):
    first = fps_shrink(first, mod)
    second = fps_shrink(second, mod)
    while second:
        first, second = (second, poly_mod(first, second, mod))
    return polynomial_monic(first, mod)

def polynomial_extended_gcd(first, second, mod=DEFAULT_MOD):
    """Return monic g, s, t satisfying s * first + t * second = g."""
    old_remainder = fps_shrink(first, mod)
    remainder = fps_shrink(second, mod)
    old_first, current_first = ([1], [])
    old_second, current_second = ([], [1])
    while remainder:
        quotient, next_remainder = poly_divmod(old_remainder, remainder, mod)
        old_remainder, remainder = (remainder, next_remainder)
        old_first, current_first = (current_first, fps_subtract(old_first, fps_multiply(quotient, current_first, mod), mod))
        old_second, current_second = (current_second, fps_subtract(old_second, fps_multiply(quotient, current_second, mod), mod))
        old_first = fps_shrink(old_first, mod)
        old_second = fps_shrink(old_second, mod)
        current_first = fps_shrink(current_first, mod)
        current_second = fps_shrink(current_second, mod)
    if not old_remainder:
        return ([], [], [])
    scale = pow(old_remainder[-1], -1, mod)
    return ([value * scale % mod for value in old_remainder], [value * scale % mod for value in old_first], [value * scale % mod for value in old_second])

# 本体
"""多項式を別の多項式で割った剰余環上の逆元と冪を計算する。"""

def polynomial_inverse_mod(polynomial, modulus, mod=DEFAULT_MOD):
    modulus = fps_shrink(modulus, mod)
    if len(modulus) <= 1:
        raise ValueError('the polynomial modulus must have positive degree')
    gcd, inverse, _ = polynomial_extended_gcd(polynomial, modulus, mod)
    if gcd != [1]:
        raise ZeroDivisionError('polynomial is not invertible modulo modulus')
    return poly_mod(inverse, modulus, mod)

def polynomial_pow_mod(polynomial, exponent, modulus, mod=DEFAULT_MOD):
    if exponent < 0:
        polynomial = polynomial_inverse_mod(polynomial, modulus, mod)
        exponent = -exponent
    modulus = fps_shrink(modulus, mod)
    if len(modulus) <= 1:
        raise ValueError('the polynomial modulus must have positive degree')
    result = [1]
    base = poly_mod(polynomial, modulus, mod)
    while exponent:
        if exponent & 1:
            result = poly_mod(fps_multiply(result, base, mod), modulus, mod)
        exponent >>= 1
        if exponent:
            base = poly_mod(fps_multiply(base, base, mod), modulus, mod)
    return result

