                half_power = polynomial_pow_mod(candidate, mod - 1 >> 1, factor, mod)
                split = polynomial_gcd(factor, fps_subtract(half_power, [1], mod), mod)
            quotient, remainder = poly_divmod(factor, split, mod)
            if remainder:
                raise ArithmeticError('finite-field factor split failed')
            stack.append(polynomial_monic(split, mod))
            stack.append(polynomial_monic(quotient, mod))
