    if not multiplicity:
        return roots
    answer = []
    remaining = source
    for root in roots:
        while len(remaining) > 1:
            quotient, remainder = _divide_linear(remaining, root, mod)
            if remainder:
                break
            answer.append(root)
            remaining = quotient
    return answer

