def modular_square_root(value, prime):
    if prime < 2:
        raise ValueError('prime must be at least 2')
    value %= prime
    if value < 2 or prime == 2:
        return value
    if pow(value, prime - 1 >> 1, prime) != 1:
        return -1
    if prime & 3 == 3:
        root = pow(value, prime + 1 >> 2, prime)
        return min(root, prime - root)
