def derangement_numbers(max_index, mod=DEFAULT_MOD):
    if max_index < 0:
        return []
    result = [0] * (max_index + 1)
    result[0] = 1
    if max_index:
        result[1] = 0
    for index in range(2, max_index + 1):
        result[index] = (index - 1) * (result[index - 1] + result[index - 2]) % mod
    return result

