"""Polynomial quotient and remainder in ascending coefficient order."""

def poly_div(dividend, divisor, mod=DEFAULT_MOD):
    """Return the polynomial quotient. O(N log N)."""
    first = fps_shrink(dividend, mod)
    second = fps_shrink(divisor, mod)
    if not second:
        raise ZeroDivisionError('polynomial division by zero')
    if len(first) < len(second):
        return []
    quotient_size = len(first) - len(second) + 1
    if len(second) <= 64:
        result = [0] * quotient_size
        remainder = first[:]
        try:
            inverse_leading = pow(second[-1], -1, mod)
        except ValueError as error:
            raise ZeroDivisionError('the leading coefficient is not invertible') from error
        width = len(second)
        for index in range(quotient_size - 1, -1, -1):
            value = remainder[index + width - 1] * inverse_leading % mod
            result[index] = value
            for offset in range(width):
                remainder[index + offset] = (remainder[index + offset] - value * second[offset]) % mod
        return result
    reversed_dividend = list(reversed(first[-quotient_size:]))
    reversed_divisor = list(reversed(second))
    result = fps_multiply(reversed_dividend, fps_inverse(reversed_divisor, quotient_size, mod), mod)[:quotient_size]
    result.reverse()
    return result

def poly_divmod(dividend, divisor, mod=DEFAULT_MOD):
    """Return ``(quotient, remainder)`` for polynomial division. O(N log N)."""
    second = fps_shrink(divisor, mod)
    if not second:
        raise ZeroDivisionError('polynomial division by zero')
    first = fps_shrink(dividend, mod)
    quotient = poly_div(first, second, mod)
    if not quotient:
        return ([], first)
    product = fps_multiply(quotient, second, mod)
    remainder = [0] * min(len(second) - 1, max(len(first), len(product)))
    for index in range(len(remainder)):
        left = first[index] if index < len(first) else 0
        right = product[index] if index < len(product) else 0
        remainder[index] = (left - right) % mod
    while remainder and remainder[-1] == 0:
        remainder.pop()
    return (quotient, remainder)

def poly_mod(dividend, divisor, mod=DEFAULT_MOD):
    """Return the remainder of polynomial division. O(N log N)."""
    return poly_divmod(dividend, divisor, mod)[1]

# 本体
def berlekamp_massey(sequence, mod=DEFAULT_MOD):
    connection = [1]
    previous = [1]
    length = 0
    shift = 1
    previous_discrepancy = 1
    for position, raw_value in enumerate(sequence):
        discrepancy = raw_value % mod
        for index in range(1, length + 1):
            discrepancy += connection[index] * sequence[position - index]
        discrepancy %= mod
        if discrepancy == 0:
            shift += 1
            continue
        try:
            scale = discrepancy * pow(previous_discrepancy, -1, mod) % mod
        except ValueError as error:
            raise ZeroDivisionError('Berlekamp-Massey requires a field') from error
        saved = connection[:]
        required = len(previous) + shift
        if len(connection) < required:
            connection.extend([0] * (required - len(connection)))
        for index, value in enumerate(previous):
            connection[index + shift] = (connection[index + shift] - scale * value) % mod
        if length * 2 <= position:
            length = position + 1 - length
            previous = saved
            previous_discrepancy = discrepancy
            shift = 1
        else:
            shift += 1
    return [-connection[index] % mod for index in range(1, length + 1)]

def berlekamp_massey_poly(sequence, mod=DEFAULT_MOD):
    coefficients = berlekamp_massey(sequence, mod)
    return [1] + [-value % mod for value in coefficients]

def bostan_mori(index, numerator, denominator, mod=DEFAULT_MOD):
    if index < 0:
        raise ValueError('index must be nonnegative')
    denominator = fps_shrink(denominator, mod)
    if not denominator:
        raise ZeroDivisionError('zero denominator')
    try:
        pow(denominator[0], -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('constant denominator is not invertible') from error
    numerator = fps_shrink(numerator, mod)
    polynomial_part = 0
    if len(numerator) >= len(denominator):
        quotient, numerator = poly_divmod(numerator, denominator, mod)
        if index < len(quotient):
            polynomial_part = quotient[index]
    if not numerator:
        return polynomial_part
    while index:
        opposite = denominator[:]
        for position in range(1, len(opposite), 2):
            opposite[position] = -opposite[position] % mod
        multiplied_numerator = fps_multiply(numerator, opposite, mod)
        multiplied_denominator = fps_multiply(denominator, opposite, mod)
        numerator = multiplied_numerator[index & 1::2]
        denominator = multiplied_denominator[::2]
        index >>= 1
        if not numerator:
            return polynomial_part
    return (polynomial_part + numerator[0] * pow(denominator[0], -1, mod)) % mod

def linear_recurrence_nth(initial, coefficients, index, mod=DEFAULT_MOD):
    if index < 0:
        raise ValueError('index must be nonnegative')
    order = len(coefficients)
    if index < len(initial):
        return initial[index] % mod
    if order == 0:
        return 0
    if len(initial) < order:
        raise ValueError('at least order initial values are required')
    denominator = [1] + [-value % mod for value in coefficients]
    numerator = fps_multiply(initial[:order], denominator, mod)[:order]
    return bostan_mori(index, numerator, denominator, mod)

def nth_term(index, sequence, mod=DEFAULT_MOD):
    if index < 0:
        raise ValueError('index must be nonnegative')
    if index < len(sequence):
        return sequence[index] % mod
    coefficients = berlekamp_massey(sequence, mod)
    if not coefficients:
        return 0
    return linear_recurrence_nth(sequence, coefficients, index, mod)

def kitamasa(index, characteristic, initial, mod=DEFAULT_MOD):
    characteristic = fps_shrink(characteristic, mod)
    if not characteristic or characteristic[0] == 0:
        raise ValueError('characteristic[0] must be nonzero')
    inverse = pow(characteristic[0], -1, mod)
    coefficients = [-value * inverse % mod for value in characteristic[1:]]
    return linear_recurrence_nth(initial, coefficients, index, mod)

