    for row in matrix:
        if len(row) != size:
            raise ValueError('polynomial matrix must be square')
    return size

def _linear_algebra_polynomial_matrix_evaluate(polynomial, point, mod):
    result = 0
    for coefficient in reversed(polynomial):
        result = (result * point + coefficient) % mod
    return result

def polynomial_matrix_determinant(matrix, mod=_fps_formal_power_series_DEFAULT_MOD):
    size = _linear_algebra_polynomial_matrix_shape(matrix)
    if size == 0:
        return [1]
    degree = 0
    for row in matrix:
        maximum = 0
        for polynomial in row:
            maximum = max(maximum, len(polynomial) - 1)
        degree += maximum
    if degree >= mod:
        raise ValueError('determinant degree must be smaller than mod')
    points = list(range(degree + 1))
    values = [0] * (degree + 1)
    evaluated = [[0] * size for _ in range(size)]
    for point in points:
        for row in range(size):
            for column in range(size):
                evaluated[row][column] = _linear_algebra_polynomial_matrix_evaluate(matrix[row][column], point, mod)
        values[point] = matrix_determinant(evaluated, mod)
    return polynomial_interpolation(points, values, mod)

