def polynomial_matrix_prefix_product(matrix, count, mod=_fps_formal_power_series_DEFAULT_MOD):
    size = _linear_algebra_polynomial_matrix_shape(matrix)
    if count < 0:
        raise ValueError('count must be nonnegative')
    if size == 0:
        return []
    if count == 0:
        return identity_matrix(size)
    degree = 1
    for row in matrix:
        for polynomial in row:
            degree = max(degree, len(polynomial) - 1)
    rounded = 1
    while rounded < degree:
        rounded <<= 1
    degree = rounded
    block = 1
    while degree * block * block < count:
        block <<= 1
    if degree * block >= mod:
        raise ValueError('sample range must be smaller than mod')
    inverse_block = pow(block, -1, mod)
    samples = []
    for index in range(degree + 1):
        point = block * index % mod
        samples.append([[_linear_algebra_polynomial_matrix_evaluate(matrix[row][column], point, mod) for column in range(size)] for row in range(size)])
    width = 1
    while width != block:
        fraction = width * inverse_block % mod
        first_shift = _linear_algebra_polynomial_matrix_shift_matrix_samples(samples, fraction, mod)
        second_shift = _linear_algebra_polynomial_matrix_shift_matrix_samples(samples, width * degree + 1, mod)
        third_shift = _linear_algebra_polynomial_matrix_shift_matrix_samples(samples, (width * degree + 1 + fraction) % mod, mod)
        boundary = width * degree + 1
        for index in range(boundary):
            samples[index] = matrix_multiply(first_shift[index], samples[index], mod)
            second_shift[index] = matrix_multiply(third_shift[index], second_shift[index], mod)
        samples.extend(second_shift[:-1])
        width <<= 1
    result = identity_matrix(size)
    index = 0
    while index + block <= count:
        result = matrix_multiply(samples[index // block], result, mod)
        index += block
    while index < count:
        point_matrix = [[_linear_algebra_polynomial_matrix_evaluate(matrix[row][column], index, mod) for column in range(size)] for row in range(size)]
