    if not series:
        raise ZeroDivisionError('the zero series is not invertible')
    try:
        first_inverse = pow(series[0] % mod, -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('the constant coefficient is not invertible') from error
    terms = _fps_formal_power_series_sparse_terms(series, degree, mod, _fps_formal_power_series_SPARSE_INV_THRESHOLD)
    if terms is not None:
        return _fps_formal_power_series_fps_inverse_sparse(degree, first_inverse, terms, mod)
    result = [first_inverse]
    current = 1
    transform = _fps_formal_power_series_DEFAULT_TRANSFORM if mod == DEFAULT_MOD else None
    if transform is None:
        try:
            transform = get_ntt(mod)
        except ValueError:
            pass
    while current < degree:
        target = min(current << 1, degree)
        direct = transform is not None
        if direct:
            try:
                transform._check_length(current << 1)
            except ValueError:
                direct = False
        if direct:
            _fps_formal_power_series_inverse_ntt_step(series, result, current, target, transform)
        else:
            product = fps_multiply(series[:target], result, mod)[:target]
            correction = [0] * target
            correction[0] = (2 - product[0]) % mod
            for index in range(1, len(product)):
                correction[index] = -product[index] % mod
            result = fps_multiply(result, correction, mod)[:target]
        current = target
    return result

def fps_div(numerator, denominator, degree=None, mod=DEFAULT_MOD):
    """Return ``numerator / denominator mod x^degree``. O(N log N)."""
    degree = _fps_formal_power_series_degree(degree, len(numerator))
    if degree == 0:
        return []
    if not denominator:
        raise ZeroDivisionError('fps division requires a denominator')
    try:
        first_inverse = pow(denominator[0] % mod, -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('denominator constant coefficient must be invertible') from error
    terms = _fps_formal_power_series_sparse_terms(denominator, degree, mod, _fps_formal_power_series_SPARSE_DIV_THRESHOLD)
    if terms is not None:
        return _fps_formal_power_series_fps_div_sparse(numerator, degree, first_inverse, terms, mod)
    inverse = fps_inverse(denominator, degree, mod)
    result = fps_multiply(numerator[:degree], inverse, mod)[:degree]
    result.extend([0] * (degree - len(result)))
    return result

def fps_logarithm(series, degree=None, mod=DEFAULT_MOD):
    """Return the formal logarithm through ``degree``; series[0] must be 1. O(N log N)."""
    degree = _fps_formal_power_series_degree(degree, len(series))
    if degree == 0:
        return []
    if not series or series[0] % mod != 1:
        raise ValueError('fps logarithm requires constant coefficient 1')
    terms = _fps_formal_power_series_sparse_terms(series, degree, mod, _fps_formal_power_series_SPARSE_LOG_THRESHOLD)
    if terms is not None:
        return _fps_formal_power_series_fps_logarithm_sparse(series, degree, terms, mod)
    product = fps_multiply(fps_derivative(series, mod), fps_inverse(series, degree, mod), mod)
    result = fps_integral(product[:degree - 1], mod)
    result.extend([0] * (degree - len(result)))
    return result

def _fps_formal_power_series_fps_exponential_ntt(series, degree, transform):
    mod = transform.mod
    b = [1, series[1] % mod if len(series) > 1 else 0]
    c = [1]
    z2 = [1, 1]
    inverse = [0, 1]
    size = 2
    while size < degree:
        doubled = size << 1
        y = b + [0] * size
        transform.butterfly(y)
        z1 = z2
        z = [y[index] * z1[index] % mod for index in range(size)]
        transform.butterfly_inv(z)
        for index in range(size >> 1):
            z[index] = 0
        transform.butterfly(z)
        for index in range(size):
            z[index] = -z[index] * z1[index] % mod
        transform.butterfly_inv(z)
        c.extend(z[size >> 1:])
        z2 = c + [0] * size
        transform.butterfly(z2)
        source_size = min(len(series), size)
        x = [series[index] % mod for index in range(source_size)]
        x.extend([0] * (size - source_size))
        x = fps_derivative(x, mod)
        x.append(0)
        transform.butterfly(x)
        for index in range(size):
            x[index] = x[index] * y[index] % mod
        transform.butterfly_inv(x)
        for index in range(1, len(b)):
            x[index - 1] = (x[index - 1] - index * b[index]) % mod
        x.extend([0] * size)
        for index in range(size - 1):
            x[size + index], x[index] = (x[index], 0)
        transform.butterfly(x)
        for index in range(doubled):
            x[index] = x[index] * z2[index] % mod
        transform.butterfly_inv(x)
        x.pop()
        for index in range(len(inverse), len(x) + 1):
            inverse.append(-inverse[mod % index] * (mod // index) % mod)
        x = [0] + [value * inverse[index + 1] % mod for index, value in enumerate(x)]
        for index in range(size):
            x[index] = 0
        for index in range(size, min(len(series), doubled)):
            x[index] = (x[index] + series[index]) % mod
        transform.butterfly(x)
        for index in range(doubled):
            x[index] = x[index] * y[index] % mod
        transform.butterfly_inv(x)
        b.extend(x[size:])
        size = doubled
    return b[:degree]

def _fps_formal_power_series_fps_exponential_newton(series, degree, mod):
    result = [1]
    while len(result) < degree:
        target = min(len(result) << 1, degree)
        logarithm = fps_logarithm(result, target, mod)
        correction = [0] * target
        for index in range(target):
            value = series[index] if index < len(series) else 0
            correction[index] = (value - logarithm[index]) % mod
        correction[0] = (correction[0] + 1) % mod
        result = fps_multiply(result, correction, mod)[:target]
    return result

def fps_exponential(series, degree=None, mod=DEFAULT_MOD):
    """Return the formal exponential through ``degree``; series[0] must be 0. O(N log N)."""
    degree = _fps_formal_power_series_degree(degree, len(series))
    if degree == 0:
        return []
    if series and series[0] % mod:
        raise ValueError('fps exponential requires constant coefficient 0')
    terms = _fps_formal_power_series_sparse_terms(series, degree, mod, _fps_formal_power_series_SPARSE_EXP_THRESHOLD)
    if terms is not None:
        return _fps_formal_power_series_fps_exponential_sparse(degree, terms, mod)
    transform = _fps_formal_power_series_DEFAULT_TRANSFORM if mod == DEFAULT_MOD else None
    try:
        if transform is None:
            transform = get_ntt(mod)
        transform._check_length(1 << (degree - 1).bit_length())
    except ValueError:
        transform = None
    if transform is not None:
        return _fps_formal_power_series_fps_exponential_ntt(series, degree, transform)
    return _fps_formal_power_series_fps_exponential_newton(series, degree, mod)

def fps_power(series, exponent, degree=None, mod=DEFAULT_MOD):
    """Raise a series to an integer power through ``degree``. O(N log N)."""
    degree = _fps_formal_power_series_degree(degree, len(series))
    if degree == 0:
        return []
    if exponent == 0:
        return [1] + [0] * (degree - 1)
    leading = 0
    while leading < len(series) and series[leading] % mod == 0:
        leading += 1
    if leading == len(series):
        if exponent < 0:
            raise ZeroDivisionError('a zero series cannot have negative exponent')
        return [0] * degree
    if exponent < 0 and leading:
        raise ValueError('negative power requires an invertible series')
    shift = leading * exponent
    if shift >= degree:
        return [0] * degree
    coefficient = series[leading] % mod
    try:
        inverse_coefficient = pow(coefficient, -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('the leading coefficient is not invertible') from error
    needed = degree - shift
    normalized = [value * inverse_coefficient % mod for value in series[leading:]]
    terms = _fps_formal_power_series_sparse_terms(normalized, needed, mod, _fps_formal_power_series_SPARSE_POWER_THRESHOLD)
    if terms is not None:
        result = _fps_formal_power_series_fps_power_unit_sparse(needed, exponent, terms, mod)
    else:
        logarithm = fps_logarithm(normalized, needed, mod)
        for index in range(needed):
            logarithm[index] = logarithm[index] * exponent % mod
        result = fps_exponential(logarithm, needed, mod)
    scale = pow(coefficient, exponent, mod)
    result = [value * scale % mod for value in result]
    return [0] * shift + result

def fps_square_root(series, degree=None, mod=DEFAULT_MOD):
    """Return one formal square root, or None when no root exists. O(N log N)."""
    degree = _fps_formal_power_series_degree(degree, len(series))
    if degree == 0:
        return []
    leading = 0
    limit = min(len(series), degree)
    while leading < limit and series[leading] % mod == 0:
        leading += 1
    if leading == limit:
        return [0] * degree
    if leading & 1:
        return None
    shift = leading >> 1
    needed = degree - shift
    source = [value % mod for value in series[leading:]]
    root = modular_square_root(source[0], mod)
    if root == -1:
        return None
    try:
        inverse_two = pow(2, -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('fps square root requires invertible 2') from error
    inverse_constant = pow(source[0], -1, mod)
    normalized = [value * inverse_constant % mod for value in source]
    terms = _fps_formal_power_series_sparse_terms(normalized, needed, mod, _fps_formal_power_series_SPARSE_POWER_THRESHOLD)
    if terms is not None:
        result = _fps_formal_power_series_fps_power_unit_sparse(needed, inverse_two, terms, mod)
        return [0] * shift + [value * root % mod for value in result]
    result = [root]
    current = 1
    while current < needed:
        target = min(current << 1, needed)
        quotient = fps_multiply(source[:target], fps_inverse(result, target, mod), mod)[:target]
        result.extend([0] * (target - len(result)))
        for index in range(target):
            value = quotient[index] if index < len(quotient) else 0
            result[index] = (result[index] + value) * inverse_two % mod
        current = target
    return [0] * shift + result[:needed]

def fps_taylor_shift(series, shift, mod=DEFAULT_MOD):
    """Return coefficients of ``f(x + shift)``. O(N log N)."""
    size = len(series)
    if size == 0:
        return []
    _fps_formal_power_series_inverses(size, mod)
    factorial = [1] * size
    for index in range(1, size):
        factorial[index] = factorial[index - 1] * index % mod
    try:
        inverse_factorial = [0] * size
        inverse_factorial[-1] = pow(factorial[-1], -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('factorial is not invertible') from error
    for index in range(size - 1, 0, -1):
        inverse_factorial[index - 1] = inverse_factorial[index] * index % mod
    left = [series[index] * factorial[index] % mod for index in range(size)]
    left.reverse()
    right = [0] * size
    power = 1
    shift %= mod
    for index in range(size):
        right[index] = power * inverse_factorial[index] % mod
        power = power * shift % mod
    product = fps_multiply(left, right, mod)
    return [product[size - 1 - index] * inverse_factorial[index] % mod for index in range(size)]

def fps_product(polynomials, mod=DEFAULT_MOD):
    """Multiply many polynomials by repeatedly combining the shortest pair. O(S log S log K)."""
    heap = []
    serial = 0
    for polynomial in polynomials:
        values = [value % mod for value in polynomial]
        if not values:
            return []
        heap.append((len(values), serial, values))
        serial += 1
    if not heap:
        return [1]
    heapify(heap)
    while len(heap) > 1:
        _, _, first = heappop(heap)
        _, _, second = heappop(heap)
        product = fps_multiply(first, second, mod)
        heappush(heap, (len(product), serial, product))
        serial += 1
    return heap[0][2]
fps_sub = fps_subtract
fps_neg = fps_negate
fps_mul = fps_multiply
fps_diff = fps_derivative
fps_inv = fps_inverse
fps_log = fps_logarithm
fps_exp = fps_exponential
fps_pow = fps_power
fps_sqrt = fps_square_root
fps_eval = fps_evaluate
tayler_shift = fps_taylor_shift

# 依存: fps/SumOfRationals.py
"""複数の有理形式的冪級数を1つの分子・分母へまとめる。"""
from heapq import heapify as _fps_sum_of_rationals_heapify, heappop as _fps_sum_of_rationals_heappop, heappush as _fps_sum_of_rationals_heappush

def sum_of_rationals(fractions, mod=DEFAULT_MOD):
    """Combine pairs (numerator, denominator) into a single rational FPS."""
    if not fractions:
        return ([0], [1])
    heap = []
    for serial, (numerator, denominator) in enumerate(fractions):
        if not denominator:
            raise ZeroDivisionError('a rational FPS denominator is zero')
        numerator = [value % mod for value in numerator]
        denominator = [value % mod for value in denominator]
        heap.append((len(numerator) + len(denominator), serial, numerator, denominator))
    _fps_sum_of_rationals_heapify(heap)
    serial = len(heap)
    while len(heap) > 1:
        _, _, first_numerator, first_denominator = _fps_sum_of_rationals_heappop(heap)
        _, _, second_numerator, second_denominator = _fps_sum_of_rationals_heappop(heap)
        numerator = fps_add(fps_multiply(first_numerator, second_denominator, mod), fps_multiply(first_denominator, second_numerator, mod), mod)
        denominator = fps_multiply(first_denominator, second_denominator, mod)
        _fps_sum_of_rationals_heappush(heap, (len(numerator) + len(denominator), serial, numerator, denominator))
        serial += 1
    _, _, numerator, denominator = heap[0]
    return (numerator, denominator)

# 依存: polynomial/PolynomialDivision.py
"""Polynomial quotient and remainder in ascending coefficient order."""

def poly_div(dividend, divisor, mod=DEFAULT_MOD):
    """Return the polynomial quotient. O(N log N)."""
    first = fps_shrink(dividend, mod)
    second = fps_shrink(divisor, mod)
    if not second:
        raise ZeroDivisionError('polynomial division by zero')
    if len(first) < len(second):
        return []
    quotient_size = len(first) - len(second) + 1
    if len(second) <= 64:
        result = [0] * quotient_size
        remainder = first[:]
        try:
            inverse_leading = pow(second[-1], -1, mod)
        except ValueError as error:
            raise ZeroDivisionError('the leading coefficient is not invertible') from error
        width = len(second)
        for index in range(quotient_size - 1, -1, -1):
            value = remainder[index + width - 1] * inverse_leading % mod
            result[index] = value
            for offset in range(width):
                remainder[index + offset] = (remainder[index + offset] - value * second[offset]) % mod
        return result
    reversed_dividend = list(reversed(first[-quotient_size:]))
    reversed_divisor = list(reversed(second))
    result = fps_multiply(reversed_dividend, fps_inverse(reversed_divisor, quotient_size, mod), mod)[:quotient_size]
    result.reverse()
    return result

def poly_divmod(dividend, divisor, mod=DEFAULT_MOD):
    """Return ``(quotient, remainder)`` for polynomial division. O(N log N)."""
    second = fps_shrink(divisor, mod)
    if not second:
        raise ZeroDivisionError('polynomial division by zero')
    first = fps_shrink(dividend, mod)
    quotient = poly_div(first, second, mod)
    if not quotient:
        return ([], first)
    product = fps_multiply(quotient, second, mod)
    remainder = [0] * min(len(second) - 1, max(len(first), len(product)))
    for index in range(len(remainder)):
        left = first[index] if index < len(first) else 0
        right = product[index] if index < len(product) else 0
        remainder[index] = (left - right) % mod
    while remainder and remainder[-1] == 0:
        remainder.pop()
    return (quotient, remainder)

def poly_mod(dividend, divisor, mod=DEFAULT_MOD):
    """Return the remainder of polynomial division. O(N log N)."""
    return poly_divmod(dividend, divisor, mod)[1]

# 依存: polynomial/MultipointEvaluation.py
def _polynomial_multipoint_evaluation_batch_inverse(values, mod):
    size = len(values)
    prefix = [1] * (size + 1)
    for index, value in enumerate(values):
        value %= mod
        if value == 0:
            raise ValueError('interpolation points must be distinct modulo mod')
        prefix[index + 1] = prefix[index] * value % mod
    try:
        inverse = pow(prefix[-1], -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('interpolation requires a field') from error
    result = [0] * size
    for index in range(size - 1, -1, -1):
        result[index] = inverse * prefix[index] % mod
        inverse = inverse * (values[index] % mod) % mod
    return result

class ProductTree:
    __slots__ = ('points', 'mod', 'n', 'size', 'products')

    def __init__(self, points, mod=DEFAULT_MOD):
        self.mod = mod
        self.points = [value % mod for value in points]
        self.n = len(self.points)
        size = 1
        while size < self.n:
            size <<= 1
        self.size = size
        products = [None] * (size << 1)
        for index, value in enumerate(self.points):
            products[size + index] = [-value % mod, 1]
        for node in range(size - 1, 0, -1):
            left = products[node << 1]
            right = products[node << 1 | 1]
            if left is None:
                products[node] = right
            elif right is None:
                products[node] = left
            else:
                products[node] = fps_multiply(left, right, mod)
        self.products = products

    @property
    def polynomial(self):
        if self.n == 0:
            return [1]
        return self.products[1][:]

    def evaluate(self, polynomial, direct_threshold=64):
        if direct_threshold < 1:
            raise ValueError('direct_threshold must be positive')
        if self.n == 0:
            return []
        mod = self.mod
        current = fps_shrink(polynomial, mod)
        if not current:
            return [0] * self.n
        root = self.products[1]
        if len(current) >= len(root):
            current = poly_mod(current, root, mod)
            if not current:
                return [0] * self.n
        result = [0] * self.n
        stack = [(1, 0, self.size, current)]
        points = self.points
        products = self.products
        limit = self.n
        while stack:
            node, left, right, values = stack.pop()
            active_right = min(right, limit)
            if left >= active_right:
                continue
            if active_right - left <= direct_threshold or len(values) <= direct_threshold:
                for point_index in range(left, active_right):
                    value = 0
                    point = points[point_index]
                    for coefficient in reversed(values):
                        value = (value * point + coefficient) % mod
                    result[point_index] = value
                continue
            middle = left + right >> 1
            right_node = node << 1 | 1
            right_product = products[right_node]
            if right_product is not None and middle < limit:
                if len(values) < len(right_product):
                    right_values = values
                else:
                    right_values = poly_mod(values, right_product, mod)
                stack.append((right_node, middle, right, right_values))
            left_node = node << 1
            left_product = products[left_node]
            if len(values) < len(left_product):
                left_values = values
            else:
                left_values = poly_mod(values, left_product, mod)
            stack.append((left_node, left, middle, left_values))
        return result

    def interpolate(self, values):
        if len(values) != self.n:
            raise ValueError('points and values must have the same length')
        if self.n == 0:
            return []
        mod = self.mod
        derivative_values = self.evaluate(fps_derivative(self.products[1], mod))
        inverse_values = _polynomial_multipoint_evaluation_batch_inverse(derivative_values, mod)
        coefficients = [None] * (self.size << 1)
        for index, value in enumerate(values):
            coefficients[self.size + index] = [value * inverse_values[index] % mod]
        products = self.products
        for node in range(self.size - 1, 0, -1):
            left_node = node << 1
            right_node = left_node | 1
            left = coefficients[left_node]
            right = coefficients[right_node]
            if left is None:
                coefficients[node] = right
            elif right is None:
                coefficients[node] = left
            else:
                coefficients[node] = fps_add(fps_multiply(left, products[right_node], mod), fps_multiply(right, products[left_node], mod), mod)
        result = coefficients[1]
        result.extend([0] * (self.n - len(result)))
        return result[:self.n]

def multipoint_evaluation(polynomial, points, mod=DEFAULT_MOD):
    return ProductTree(points, mod).evaluate(polynomial)

def polynomial_interpolation(points, values, mod=DEFAULT_MOD):
    return ProductTree(points, mod).interpolate(values)

def interpolate_consecutive(values, point, mod=DEFAULT_MOD):
    size = len(values)
    if size == 0:
        raise ValueError('at least one value is required')
    if size > mod:
        raise ValueError('the number of points must not exceed mod')
    point %= mod
    if point < size:
        return values[point] % mod
    left = [1] * (size + 1)
    right = [1] * (size + 1)
    for index in range(size):
        left[index + 1] = left[index] * (point - index) % mod
    for index in range(size - 1, -1, -1):
        right[index] = right[index + 1] * (point - index) % mod
    factorial = 1
    for index in range(2, size):
        factorial = factorial * index % mod
    try:
        inverse_factorial = pow(factorial, -1, mod)
    except ValueError as error:
        raise ZeroDivisionError('interpolation requires a field') from error
    inverse_factorials = [1] * size
    if size > 1:
        inverse_factorials[-1] = inverse_factorial
        for index in range(size - 1, 0, -1):
            inverse_factorials[index - 1] = inverse_factorials[index] * index % mod
    result = 0
    last = size - 1
    for index, value in enumerate(values):
        term = value * left[index] * right[index + 1] * inverse_factorials[index] * inverse_factorials[last - index] % mod
        if last - index & 1:
            result -= term
        else:
            result += term
    return result % mod

def _polynomial_multipoint_evaluation_sample_point_shift_segment(values, point, count, mod):
    degree = len(values) - 1
    factorial = 1
    for index in range(2, degree + 1):
        factorial = factorial * index % mod
    inverse_factorial = [1] * (degree + 1)
    if degree:
        inverse_factorial[-1] = pow(factorial, -1, mod)
        for index in range(degree, 0, -1):
            inverse_factorial[index - 1] = inverse_factorial[index] * index % mod
    weighted = [0] * (degree + 1)
    for index, value in enumerate(values):
        weighted[index] = value * inverse_factorial[index] * inverse_factorial[degree - index] % mod
        if degree - index & 1:
            weighted[index] = -weighted[index] % mod
    reciprocals = [0] * (count + degree)
    for index in range(len(reciprocals)):
        reciprocals[index] = pow(point - degree + index, -1, mod)
    product = fps_multiply(weighted, reciprocals, mod)
    falling = point % mod
    for index in range(1, degree + 1):
        falling = falling * (point - index) % mod
    result = [0] * count
    for index in range(count):
        result[index] = falling * product[degree + index] % mod
        falling = falling * (point + index + 1) % mod
        falling = falling * reciprocals[index] % mod
    return result

def sample_point_shift(values, point, count=None, mod=DEFAULT_MOD):
    if not values:
        raise ValueError('at least one sample is required')
    if count is None:
        count = len(values)
    if count < 0:
        raise ValueError('count must be nonnegative')
    if len(values) > mod:
        raise ValueError('the number of samples must not exceed mod')
    if count == 0:
        return []
    degree = len(values) - 1
    current = point % mod
    remaining = count
    result = []
    while remaining:
        segment = min(remaining, mod - current)
        if current <= degree:
            copied = min(segment, degree - current + 1)
            result.extend((value % mod for value in values[current:current + copied]))
            current += copied
            remaining -= copied
            segment -= copied
            if remaining == 0:
                break
            if current == mod:
                current = 0
                continue
        if segment:
            result.extend(_polynomial_multipoint_evaluation_sample_point_shift_segment(values, current, segment, mod))
            current += segment
            remaining -= segment
        if current == mod:
            current = 0
    return result
MultipointEvaluation = multipoint_evaluation
PolynomialInterpolation = polynomial_interpolation
Interpolate = interpolate_consecutive
SamplePointShift = sample_point_shift

# 依存: fps/CompositeExponential.py
"""合成指数型母関数とその逆変換を計算する。"""

def composite_exponential(polynomial, degree, mod=DEFAULT_MOD):
    """Return the first ``degree`` coefficients of f(exp(x))."""
    if degree < 0:
        raise ValueError('degree must be nonnegative')
    if degree == 0:
        return []
    fractions = [([coefficient % mod], [1, -index % mod]) for index, coefficient in enumerate(polynomial)]
    numerator, denominator = sum_of_rationals(fractions, mod)
    result = fps_multiply(numerator, fps_inverse(denominator, degree, mod), mod)[:degree]
    result.extend([0] * (degree - len(result)))
    inverse_factorial = 1
    for index in range(1, degree):
        inverse_factorial = inverse_factorial * pow(index, -1, mod) % mod
        result[index] = result[index] * inverse_factorial % mod
    return result

def composite_exponential_scaled(polynomial, scale=1, degree=None, mod=DEFAULT_MOD):
    """Return f(exp(scale*x)) modulo x**degree."""
    if degree is None:
        degree = len(polynomial)
    if scale % mod == 0:
        raise ValueError('scale must be nonzero')
    if degree == 0 or not polynomial:
        return []
    fractions = [([coefficient % mod], [1, -scale * index % mod]) for index, coefficient in enumerate(polynomial)]
    numerator, denominator = sum_of_rationals(fractions, mod)
    result = fps_multiply(numerator, fps_inverse(denominator, degree, mod), mod)[:degree]
    result.extend([0] * (degree - len(result)))
    inverse_factorial = 1
    for index in range(1, degree):
        inverse_factorial = inverse_factorial * pow(index, -1, mod) % mod
        result[index] = result[index] * inverse_factorial % mod
    return result

def inverse_composite_exponential(series, scale=1, mod=DEFAULT_MOD):
    """Invert ``composite_exponential_scaled`` for equal input/output size."""
    size = len(series)
    if size == 0:
        return []
    scale %= mod
    if scale == 0:
        raise ValueError('scale must be nonzero')
    moments = [0] * size
    factorial = 1
    for index, value in enumerate(series):
        if index:
            factorial = factorial * index % mod
        moments[index] = value * factorial % mod
    points = [scale * index % mod for index in range(size)]
    tree = ProductTree(points, mod)
    reversed_denominator = tree.polynomial[::-1]
    numerator = fps_multiply(moments, reversed_denominator, mod)[:size]
    evaluations = tree.evaluate(numerator[::-1])
    factorials = [1] * size
    for index in range(1, size):
        factorials[index] = factorials[index - 1] * index % mod
    scale_power = pow(scale, size - 1, mod)
    result = [0] * size
    last = size - 1
    for index in range(size):
        denominator = scale_power * factorials[index] % mod * factorials[last - index] % mod
        if last - index & 1:
            denominator = -denominator % mod
        result[index] = evaluations[index] * pow(denominator, -1, mod) % mod
    return result

# 依存: combinatorial_series/PascalTransform.py
"""列へPascal変換または逆変換を適用する。"""

def _combinatorial_series_pascal_transform_factorials(size, mod):
    if size >= mod:
        raise ValueError('series degree must be smaller than mod')
    factorial = [1] * (size + 1)
    for index in range(1, size + 1):
        factorial[index] = factorial[index - 1] * index % mod
    inverse_factorial = [1] * (size + 1)
    if size:
        inverse_factorial[-1] = pow(factorial[-1], -1, mod)
        for index in range(size, 0, -1):
            inverse_factorial[index - 1] = inverse_factorial[index] * index % mod
    return (factorial, inverse_factorial)

def pascal_transform(values, inverse=False, transpose=False, mod=DEFAULT_MOD):
    """Apply binom(i,j), or its transpose; inverse toggles binomial inversion."""
    size = len(values)
    if size == 0:
        return []
    factorial, inverse_factorial = _combinatorial_series_pascal_transform_factorials(size - 1, mod)
    sign = -1 if inverse else 1
    kernel = [inverse_factorial[index] * (sign if index & 1 else 1) % mod for index in range(size)]
    if not transpose:
        scaled = [values[index] * inverse_factorial[index] % mod for index in range(size)]
        product = fps_multiply(scaled, kernel, mod)[:size]
        return [product[index] * factorial[index] % mod for index in range(size)]
    scaled = [values[index] * factorial[index] % mod for index in range(size)]
    scaled.reverse()
    product = fps_multiply(scaled, kernel, mod)[:size]
    product.reverse()
    return [product[index] * inverse_factorial[index] % mod for index in range(size)]

# 本体
def _factorials(size, mod):
    factorial = [1] * size
    for index in range(1, size):
        factorial[index] = factorial[index - 1] * index % mod
    inverse = [1] * size
    if size:
        inverse[-1] = pow(factorial[-1], -1, mod)
        for index in range(size - 1, 0, -1):
            inverse[index - 1] = inverse[index] * index % mod
    return (factorial, inverse)

def stirling_matrix(values, inverse=False, mod=DEFAULT_MOD):
    size = len(values)
    if size == 0:
        return []
    factorial, inverse_factorial = _factorials(size, mod)
    scaled = [values[index] * inverse_factorial[index] % mod for index in range(size)]
    if not inverse:
        transformed = pascal_transform(scaled, inverse=True, transpose=True, mod=mod)
        result = composite_exponential_scaled(transformed, 1, size, mod)
    else:
        transformed = inverse_composite_exponential(scaled, 1, mod)
        result = pascal_transform(transformed, inverse=False, transpose=True, mod=mod)
    return [result[index] * factorial[index] % mod for index in range(size)]

def stirling_matrix_transpose(values, inverse=False, mod=DEFAULT_MOD):
    size = len(values)
    if size == 0:
        return []
    factorial, inverse_factorial = _factorials(size, mod)
    tree = ProductTree(range(size), mod)
    if not inverse:
        evaluated = tree.evaluate(values)
        transformed = pascal_transform(evaluated, inverse=True, mod=mod)
        return [transformed[index] * inverse_factorial[index] % mod for index in range(size)]
    scaled = [values[index] * factorial[index] % mod for index in range(size)]
    transformed = pascal_transform(scaled, inverse=False, mod=mod)
    return tree.interpolate(transformed)
stirling_matrix_trans = stirling_matrix_transpose

