                    left += 1
                if right & 1:
                    right -= 1
                    res += data[right]
                left >>= 1
                right >>= 1
            return res
        if cmd == 1:
            res = INF
            data = self.min1
            while left < right:
                if left & 1:
                    res = min(res, data[left])
                    left += 1
                if right & 1:
                    right -= 1
                    res = min(res, data[right])
                left >>= 1
                right >>= 1
            return res
        res = -INF
        data = self.max1
        while left < right:
            if left & 1:
                res = max(res, data[left])
                left += 1
            if right & 1:
                right -= 1
                res = max(res, data[right])
            left >>= 1
            right >>= 1
        return res

    def range_sum(self, l, r):
        return self._range_query(l, r, 0)

    def range_min(self, l, r):
        return self._range_query(l, r, 1)

    def range_max(self, l, r):
        return self._range_query(l, r, 2)

    query_sum = range_sum
    query_min = range_min
    query_max = range_max

