        node = self._find(key)
        if node < 0:
            return False
        while self.left[node] >= 0 or self.right[node] >= 0:
            left = self.left[node]
            right = self.right[node]
            if right < 0 or (
                left >= 0 and self.priority[left] < self.priority[right]
            ):
                self._rotate(left)
            else:
                self._rotate(right)
        parent = self.parent[node]
        if parent < 0:
            self.root = -1
        elif self.left[parent] == node:
            self.left[parent] = -1
        else:
            self.right[parent] = -1
        self._update_up(parent)
        return True

