    def bisect_right(self, key):
        node = self.root
        result = 0
        while node >= 0:
            left = self.left[node]
            left_size = self.size[left] if left >= 0 else 0
            if self.key[node] <= key:
                result += left_size + 1
                node = self.right[node]
            else:
                node = left
        return result

    upper_bound = bisect_right

