                    node += [0] * (branch - len(node))
                    pool.extend(node)
                    nxt.append((len(pool) >> shift) - 1)
                level = nxt
            root = level[0]

        self.n = n
        self.default = default
        self.shift = shift
        self.branch = branch
        self.mask = branch - 1
        self.height = height
        self.pool = pool
        self.roots = [root]

