        assert 0 <= index < self.n
        pool = self.pool
        shift = self.shift
        mask = self.mask
        for level in range(self.height - 1, 0, -1):
            if root == 0:
                return self.default
            root = pool[(root << shift) + (index >> (level * shift) & mask)]
        return self.default if root == 0 else pool[(root << shift) + (index & mask)]

