class TwoSAT:
    """2-SAT with the node convention ``2*v=false, 2*v+1=true``."""

    __slots__ = ("n", "graph", "answer")

    def __init__(self, n):
        self.n = n
        self.graph = [[] for _ in range(n << 1)]
        self.answer = None

