        n = left_size + self.right_size
        graph = [[] for _ in range(n)]
        reverse = [[] for _ in range(n)]
        for left, edges in enumerate(self.graph):
            matched = self.match_left[left]
            for right in edges:
                rv = left_size + right
                graph[left].append(rv)
                reverse[rv].append(left)
