        for left, right in enumerate(self.match_left):
            if right == -1:
                used[left] = True
                que.append(left)
        for v in que:
            vinf.append(v)
            for to in graph[v]:
                if not used[to]:
                    used[to] = True
                    que.append(to)

        vzero = []
        que = []
        for right, left in enumerate(self.match_right):
            v = left_size + right
            if left == -1 and not used[v]:
                used[v] = True
                que.append(v)
        for v in que:
            vzero.append(v)
            for to in reverse[v]:
                if not used[to]:
                    used[to] = True
                    que.append(to)

