        self.step = value
        self.size = size
        self.period = period
        self.mod = mod

    def find(self, value):
        elapsed = 0
        baby = self.baby
        step = self.step
        mod = self.mod
        size = self.size
        period = self.period
        while elapsed < period:
            exponent = baby.get(value)
            if exponent is not None:
