class _DashedSplay:
    __slots__ = ("rake",)

    def __init__(self, rake):
        self.rake = rake

    def _update(self, node):
        value = node.key
        if node.left is not None:
            value = self.rake(value, node.left.sum)
        if node.right is not None:
            value = self.rake(value, node.right.sum)
        node.sum = value

    def _rotate_right(self, node):
        parent = node.parent
        grandparent = parent.parent
        parent.left = node.right
        if node.right is not None:
            node.right.parent = parent
        node.right = parent
        parent.parent = node
        self._update(parent)
        self._update(node)
        node.parent = grandparent
        if grandparent is not None:
            if grandparent.left is parent:
                grandparent.left = node
            if grandparent.right is parent:
                grandparent.right = node

    def _rotate_left(self, node):
        parent = node.parent
        grandparent = parent.parent
        parent.right = node.left
        if node.left is not None:
            node.left.parent = parent
        node.left = parent
        parent.parent = node
        self._update(parent)
        self._update(node)
        node.parent = grandparent
        if grandparent is not None:
            if grandparent.left is parent:
                grandparent.left = node
            if grandparent.right is parent:
                grandparent.right = node

    def splay(self, node):
        while node.parent is not None:
            parent = node.parent
            grandparent = parent.parent
            if grandparent is None:
                if parent.left is node:
                    self._rotate_right(node)
                else:
                    self._rotate_left(node)
            elif grandparent.left is parent:
                if parent.left is node:
                    self._rotate_right(parent)
                    self._rotate_right(node)
                else:
                    self._rotate_left(node)
                    self._rotate_right(node)
            else:
                if parent.right is node:
                    self._rotate_left(parent)
                    self._rotate_left(node)
                else:
                    self._rotate_right(node)
                    self._rotate_left(node)

    @staticmethod
    def _rightmost(node):
        while node.right is not None:
            node = node.right
        return node

    def insert(self, root, value):
        created = _DashedNode(value)
        if root is None:
            return created
        current = self._rightmost(root)
        self.splay(current)
        created.parent = current
        current.right = created
        self._update(current)
        self.splay(created)
        return created

    def erase(self, node):
        self.splay(node)
        left = node.left
        right = node.right
        if left is None:
            if right is not None:
                right.parent = None
            return right
        if right is None:
            left.parent = None
            return left
        left.parent = None
        root = self._rightmost(left)
        self.splay(root)
        root.right = right
        right.parent = root
        self._update(root)
        return root


