MASK64 = (1 << 64) - 1


def _mix64(value):
    value = (value + 0x9E3779B97F4A7C15) & MASK64
    value = ((value ^ (value >> 30)) * 0xBF58476D1CE4E5B9) & MASK64
    value = ((value ^ (value >> 27)) * 0x94D049BB133111EB) & MASK64
    return value ^ (value >> 31)


def _parent_order(tree, root):
    n = len(tree)
    assert 0 <= root < n
    if sum(map(len, tree)) != (n - 1) << 1:
        raise ValueError("the graph must be a tree")
    parent = [-2] * n
    parent[root] = -1
    order = [root]
    for v in order:
        p = parent[v]
        for to in tree[v]:
            if not 0 <= to < n:
                raise ValueError("the graph must be a tree")
            if to == p:
                continue
            if parent[to] != -2:
                raise ValueError("the graph must be a tree")
            parent[to] = v
            order.append(to)
    if len(order) != n:
        raise ValueError("the graph must be connected")
    return parent, order


class AHUInterner:
    __slots__ = ("mapping",)

    def __init__(self):
        self.mapping = {(): 0}

    def intern(self, signature):
        mapping = self.mapping
        class_id = mapping.get(signature)
        if class_id is None:
            class_id = len(mapping)
            mapping[signature] = class_id
        return class_id

    def __len__(self):
        return len(self.mapping)


class RootedTreeIsomorphism:
