        self.prefix.append(_string_rolling_hash_fma(self.prefix[-1], self.base, value))
        self.power.append(_string_rolling_hash_mul(self.power[-1], self.base))
        if self.base2 is not None:
            self.prefix2.append(_string_rolling_hash_fma(self.prefix2[-1], self.base2, value))
            self.power2.append(_string_rolling_hash_mul(self.power2[-1], self.base2))
