            self.append(symbol)
        return self
    connect = extend

    def __getitem__(self, index):
        if isinstance(index, slice):
            (left, right, step) = index.indices(self.n)
            if step != 1:
                return self.data[index]
            return RollingHashView(self, left, right)
        return self.data[index]

class DoubleRollingHash(RollingHash):
    __slots__ = ()

    def __init__(self, sequence=(), bases=None, reversible=False):
        if bases is None:
            bases = (DEFAULT_BASE, DEFAULT_BASE2)
        super().__init__(sequence, bases[0], bases[1], reversible)

class ReversibleRollingHash(RollingHash):
    __slots__ = ()

    def __init__(self, sequence=(), base=DEFAULT_BASE, base2=None):
        super().__init__(sequence, base, base2, True)

class RollingHashView:
    __slots__ = ('base', 'left', 'right', 'l', 'r')

    def __init__(self, base, left, right):
        self.base = base
        self.left = left
        self.right = right
        self.l = left
        self.r = right

    def __len__(self):
        return self.right - self.left

    @property
    def hash(self):
        return self.base.get(self.left, self.right)

    def to_hash_string(self):
        return self.base.get_value(self.left, self.right)

    def lcp(self, other):
        return self.base.lcp(other.base, self.left, self.right, other.left, other.right)
    LCP = lcp

    def compare(self, other):
        return self.base.compare(other.base, self.left, self.right, other.left, other.right)
    cmp = compare

    def is_palindrome(self):
        return self.to_hash_string().is_palindrome()

    def reversed(self):
        return self.to_hash_string().reversed()

    def __getitem__(self, index):
        if isinstance(index, slice):
            (left, right, step) = index.indices(len(self))
            if step != 1:
                return self.base.data[self.left:self.right][index]
            return RollingHashView(self.base, self.left + left, self.left + right)
        if index < 0:
            index += len(self)
        if not 0 <= index < len(self):
            raise IndexError('rolling hash view index out of range')
        return self.base.data[self.left + index]

    def __eq__(self, other):
        return isinstance(other, RollingHashView) and len(self) == len(other) and (self.base.bases == other.base.bases) and (self.hash == other.hash)

    def __lt__(self, other):
        return self.compare(other) < 0

    def __str__(self):
        return str(self.base.data[self.left:self.right])

# 本体
class DynamicRollingHash:
    __slots__ = ('n', 'size', 'base', 'data', 'power', 'forward', 'reverse', 'length')

    def __init__(self, sequence=(), base=DEFAULT_BASE):
        sequence = list(sequence)
        n = len(sequence)
        size = 1
        while size < n:
            size <<= 1
        power = [1] * (n + 1)
        for i in range(n):
            power[i + 1] = _string_rolling_hash_mul(power[i], base)
        forward = [0] * (size << 1)
        reverse = [0] * (size << 1)
        length = [0] * (size << 1)
        for (i, symbol) in enumerate(sequence):
            value = _string_rolling_hash_symbol_value(symbol)
            position = size + i
            forward[position] = reverse[position] = value
            length[position] = 1
        for position in range(size - 1, 0, -1):
            left = position << 1
            right = left | 1
            left_length = length[left]
            right_length = length[right]
            length[position] = left_length + right_length
            forward[position] = _string_rolling_hash_fma(forward[left], power[right_length], forward[right])
            reverse[position] = _string_rolling_hash_fma(reverse[right], power[left_length], reverse[left])
        self.n = n
        self.size = size
        self.base = base
        self.data = sequence
        self.power = power
        self.forward = forward
        self.reverse = reverse
        self.length = length

    def __len__(self):
        return self.n

    def update(self, index, value):
        assert 0 <= index < self.n
        self.data[index] = value
        position = self.size + index
        value = _string_rolling_hash_symbol_value(value)
        self.forward[position] = self.reverse[position] = value
        position >>= 1
        while position:
            left = position << 1
            right = left | 1
            left_length = self.length[left]
            right_length = self.length[right]
            self.forward[position] = _string_rolling_hash_fma(self.forward[left], self.power[right_length], self.forward[right])
            self.reverse[position] = _string_rolling_hash_fma(self.reverse[right], self.power[left_length], self.reverse[left])
            position >>= 1
    set = update

    def _query(self, left, right):
        assert 0 <= left <= right <= self.n
        left += self.size
        right += self.size
        left_forward = left_reverse = left_length = 0
        right_forward = right_reverse = right_length = 0
        while left < right:
            if left & 1:
                node_length = self.length[left]
                left_forward = _string_rolling_hash_fma(left_forward, self.power[node_length], self.forward[left])
                left_reverse = _string_rolling_hash_fma(self.reverse[left], self.power[left_length], left_reverse)
                left_length += node_length
                left += 1
            if right & 1:
                right -= 1
                node_length = self.length[right]
                right_forward = _string_rolling_hash_fma(self.forward[right], self.power[right_length], right_forward)
                right_reverse = _string_rolling_hash_fma(right_reverse, self.power[node_length], self.reverse[right])
                right_length += node_length
            left >>= 1
            right >>= 1
        forward = _string_rolling_hash_fma(left_forward, self.power[right_length], right_forward)
        reverse = _string_rolling_hash_fma(right_reverse, self.power[left_length], left_reverse)
        return (forward, reverse, left_length + right_length)

    def get(self, left=0, right=None):
        if right is None:
            right = self.n
        return self._query(left, right)[0]
    query = get

    def reverse_get(self, left=0, right=None):
        if right is None:
            right = self.n
        return self._query(left, right)[1]

    def get_value(self, left=0, right=None):
        if right is None:
            right = self.n
        (forward, reverse, length) = self._query(left, right)
        return HashString(forward, self.power[length], length, (self.base,), reverse)

    def same(self, left1, right1, left2, right2):
        return right1 - left1 == right2 - left2 and self.get(left1, right1) == self.get(left2, right2)

    def is_palindrome(self, left=0, right=None):
        if right is None:
            right = self.n
        (forward, reverse, _) = self._query(left, right)
        return forward == reverse

    def lcp(self, left1, right1, left2, right2):
        length = min(right1 - left1, right2 - left2)
        low = 0
        high = length + 1
        while high - low > 1:
            middle = low + high >> 1
            if self.get(left1, left1 + middle) == self.get(left2, left2 + middle):
                low = middle
            else:
                high = middle
        return low

    def __getitem__(self, index):
        return self.data[index]

