        data = node.data
        left = _Leaf(data[:position]) if position else None
        right = _Leaf(data[position:]) if position < node.size else None
    while path:
        side, fixed = path.pop()
        if side == 0:
            right = _join(right, fixed)
        else:
            left = _join(fixed, left)
    return left, right


