            raise IndexError('static string range is out of range')
        self.base = base
        self.left = self.l = left
        self.right = self.r = right

    @classmethod
    def from_sequence(cls, sequence):
        return StaticStringBase(sequence).view()
    from_string = from_sequence

    def __len__(self):
