        seen_left = bytearray(self.left_size)
        seen_right = bytearray(self.right_size)
        seen_left[element] = 1
        queue = [element]
        for left in queue:
            for right in self.graph[left]:
                if seen_right[right]:
                    continue
                seen_right[right] = 1
                matched = self.match_right[right]
                if matched < 0:
                    return []
                if not seen_left[matched]:
                    seen_left[matched] = 1
                    queue.append(matched)
