    selections = [selected[:]]
    total = 0
    source = size
    sink = size + 1
    infinity = 10 ** 100
    scale = size + 1
    while True:
        first.set(selected)
        second.set(selected)
        graph = [[] for _ in range(size + 2)]
        for element in range(size):
            if selected[element]:
                continue
            circuit = first.circuit(element)
            edge_cost = weights[element] * scale + 1
            if not circuit:
                graph[source].append((element, edge_cost))
            else:
                for old in circuit:
                    if old != element:
                        graph[old].append((element, edge_cost))
            circuit = second.circuit(element)
            if not circuit:
                graph[element].append((sink, 0))
            else:
                for old in circuit:
