        if len(costs) != size:
            raise ValueError("invalid unary cost length")
        self.project.add_constant_cost(costs[-1])
        for state in range(1, size):
            self.project.add_unary_cost(
                self.positions[variable][state],
                0,
                costs[state - 1] - costs[state],
            )

