                    costs[x][y]
                    - costs[x][y - 1]
                    - costs[x - 1][y]
                    + costs[x - 1][y - 1]
                )
                if difference > 0:
                    raise ValueError("pair cost must be Monge")
                self.project.add_profit_00(
                    self.positions[first][x],
                    self.positions[second][y],
