        if self.exponent == 0 and self.numerator > 0:
            return (SurrealNumber(self.numerator * 2 - 1, 1), SurrealNumber(self.numerator + 1))
        if self.exponent == 0:
            return (SurrealNumber(self.numerator - 1), SurrealNumber(self.numerator * 2 + 1, 1))
        difference = SurrealNumber(1, self.exponent + 1)
        return (self - difference, self + difference)
