            seed = seed + 11400714819323198485 & _random_random_MASK64
            value = seed
            value = (value ^ value >> 30) * 13787848793156543929 & _random_random_MASK64
            value = (value ^ value >> 27) * 10723151780598845931 & _random_random_MASK64
            state.append((value ^ value >> 31) & _random_random_MASK64)
        self.state = state

    @staticmethod
    def _rotate(value, shift):
        return (value << shift | value >> 64 - shift) & _random_random_MASK64

    def next_u64(self):
        """Return the next unsigned 64-bit integer."""
        state = self.state
        result = self._rotate(state[1] * 5 & _random_random_MASK64, 7) * 9 & _random_random_MASK64
        temporary = state[1] << 17 & _random_random_MASK64
        state[2] ^= state[0]
        state[3] ^= state[1]
        state[1] ^= state[2]
        state[0] ^= state[3]
        state[2] ^= temporary
        state[3] = self._rotate(state[3], 45)
